(()=>{
'use strict';
const KEY='SDF_RUNTIME_ERRORS298',MAX=50;
const SCREENS=new Set(['dashboard','recruiting','roster','gameday','gameplan','program','facilities','portal','shop','coach','team','rankings','stats','history','postseason','season','unknown']);
const OPS=new Set(['showTab','setSubview','advanceWeek','playPostseason','playChampionshipWeek','finishOffseason','openLiveGameCenter','global','promise','resource']);
const NAMES=new Set(['TypeError','ReferenceError','RangeError','SyntaxError','Error','SecurityError','QuotaExceededError','AbortError','Unknown']);
const FILES=new Set(['app-bundle.js','browser-growth.js','browser-bootstrap.js','web-shell.js','browser-save-bridge.js','browser-editors.js','browser-commerce-bridge.js','browser-feedback.js','browser-team-editor-v195.js','cloud-account-scope.js','browser-growth-analytics.js','browser-landing.js','capacitor.js','capacitor-plugins.js','unknown']);
const CODES=new Set(['null_access','undefined_access','missing_function','not_defined','stack_limit','syntax','promise_rejection','resource_load','other']);
let persistTimer=null,lastPersist=0;let rows=[],recent=new WeakMap(),lastPrimitive={key:'',at:0};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(saved))rows=saved.slice(-MAX).map(cleanRow).filter(Boolean)}catch{}
function localEnabled(){try{return JSON.parse(localStorage.getItem('SDF_DEVICE_DIAGNOSTICS_V236')||'null')?.enabled!==false}catch{return true}}
function save(force=false){const now=Date.now();if(!force&&now-lastPersist<1000){if(!persistTimer)persistTimer=setTimeout(()=>{persistTimer=null;save(true)},1000);return}if(persistTimer&&typeof clearTimeout==='function')clearTimeout(persistTimer);persistTimer=null;try{localStorage.setItem(KEY,JSON.stringify(rows));lastPersist=now}catch{}}
function screen(){try{const id=document.querySelector?.('.tab-page:not(.hidden)')?.id?.replace(/Tab$/,'');return SCREENS.has(id)?id:'unknown'}catch{return 'unknown'}}
function source(raw){try{const file=String(raw||'').split(/[?#]/)[0].split(/[\\/]/).at(-1);return FILES.has(file)?file:'unknown'}catch{return 'unknown'}}
function number(n){return Number.isSafeInteger(Number(n))&&Number(n)>0&&Number(n)<=2000000?Number(n):0}

function code(error,kind){const msg=String(error?.message||'');if(/null/i.test(msg)&&/properties|property|object/i.test(msg))return 'null_access';if(/undefined/i.test(msg)&&/properties|property|object/i.test(msg))return 'undefined_access';if(/not a function/i.test(msg))return 'missing_function';if(/not defined/i.test(msg))return 'not_defined';if(/call stack|recursion/i.test(msg))return 'stack_limit';if(error?.name==='SyntaxError')return 'syntax';return kind==='promise'?'promise_rejection':kind==='resource'?'resource_load':'other'}
function cleanRow(r){if(!Number.isFinite(Date.parse(r?.first))||!Number.isFinite(Date.parse(r?.last)))return null;if(!r||!CODES.has(r.error_code))return null;return{build:number(r.build),error_code:r.error_code,error_name:NAMES.has(r.error_name)?r.error_name:'Unknown',error_file:source(r.error_file),error_line:number(r.error_line),error_column:number(r.error_column),error_operation:OPS.has(r.error_operation)?r.error_operation:'global',context:SCREENS.has(r.context)?r.context:'unknown',count:Math.max(1,Math.min(1000000,number(r.count)||1)),first:new Date(r.first).toISOString(),last:new Date(r.last).toISOString()}}
function fingerprint(r){return [r.build,r.error_code,r.error_name,r.error_file,r.error_line,r.error_column,r.error_operation,r.context].join(':')}
function capture(error,operation='global',event={}){
 try{
  const now=Date.now();if(error&&typeof error==='object'){const previous=recent.get(error);if(previous!=null&&now-previous<250)return;recent.set(error,now)}
  let file=source(event.filename),line=number(event.lineno),column=number(event.colno);
  // Only shipped source basenames and numeric coordinates survive. Never retain
  // exception messages, function arguments, URL queries or raw stack text.
  if(file==='unknown'&&error?.stack){const match=String(error.stack).slice(0,10000).match(/(?:[\\/])([A-Za-z0-9_.-]+\.js):(\d+):(\d+)/);if(match){file=source(match[1]);line=number(match[2]);column=number(match[3])}}
  const build=number(String(document.getElementById?.('releaseLabel')?.textContent||'').match(/\bBuild\s+(\d+)/i)?.[1]);
  const item={build,error_code:code(error,operation),error_name:NAMES.has(error?.name)?error.name:'Unknown',error_file:file,error_line:line,error_column:column,error_operation:OPS.has(operation)?operation:'global',context:screen(),count:1,first:new Date(now).toISOString(),last:new Date(now).toISOString()},key=fingerprint(item);
  if(!error||typeof error!=='object'){if(lastPrimitive.key===key&&now-lastPrimitive.at<250)return;lastPrimitive={key,at:now}}
  if(localEnabled()){const existing=rows.find(r=>fingerprint(r)===key);if(existing){existing.count=Math.min(1000000,existing.count+1);existing.last=item.last}else{rows.push(item);rows=rows.slice(-MAX)}save()}
  const failed=['advanceWeek','playPostseason','playChampionshipWeek','finishOffseason'].includes(operation)?'simulation_failed':operation==='openLiveGameCenter'?'live_resume_failed':'runtime_error';
  const reason=failed==='simulation_failed'?'simulation':failed==='live_resume_failed'?'resume':'runtime';
  window.SDF_USAGE?.technical?.(failed,reason,item);
 }catch{}
}
function list(){return rows.map(r=>({...r})).sort((a,b)=>b.last.localeCompare(a.last))}
function clear(){rows=[];save(true);render()}
function render(){try{
 const host=document.getElementById?.('deviceDiagnosticsV236');if(!host||!document.createElement)return;
 let section=document.getElementById('runtimeErrors298');if(!section){section=document.createElement('details');section.id='runtimeErrors298';section.className='runtime-errors298';host.append(section)}
 const opened=section.open;section.replaceChildren();section.open=opened;
 const title=document.createElement('summary');title.textContent=`Error list · ${rows.length} grouped issues`;section.append(title);
 const info=document.createElement('p');info.textContent='Source locations and repeat counts stay on this device and are included in Export diagnostics. No raw exception text or save data is collected. Online reports follow Usage & privacy.';section.append(info);
 if(!rows.length){const empty=document.createElement('p');empty.textContent='No captured errors on this device.';section.append(empty)}
 for(const r of list()){const card=document.createElement('article');card.className='runtime-error298';const h=document.createElement('strong');h.textContent=`${r.error_name} · ${r.error_code.replaceAll('_',' ')} · ×${r.count}`;const p=document.createElement('p');p.textContent=`Build ${r.build||'?'} · ${r.context} · ${r.error_operation}\n${r.error_file}:${r.error_line}:${r.error_column}\nLast seen ${r.last}`;card.append(h,p);section.append(card)}
 }catch{}}
window.SDF_ERRORS={capture,list,clear,render,flush:()=>save(true)};
const emit=(...a)=>{try{window.SDF_USAGE?.record(...a)}catch{}};
const pageEvents={recruiting:'recruiting_opened',portal:'portal_opened',facilities:'facilities_opened',gameplan:'gameplan_opened'},seen=new Set();
function visit(tab){if(pageEvents[tab]&&!seen.has(tab)){seen.add(tab);emit(pageEvents[tab],undefined,undefined,{context:tab})}}
function wrap(name,after){const fn=window[name];if(typeof fn!=='function')return;window[name]=function(...args){try{const value=fn.apply(this,args);if(value&&typeof value.then==='function')return value.then(v=>{after?.(v,args);return v},error=>{capture(error,name);throw error});after?.(value,args);return value}catch(error){capture(error,name);throw error}}}
function install(){
 wrap('showTab',(v,args)=>visit(String(args[0]||'').replace(/Tab$/,'')));
 wrap('setSubview',(v,args)=>visit(String(args[1]||'')));
 for(const name of ['advanceWeek','playPostseason','playChampionshipWeek','finishOffseason'])wrap(name);
 const open=window.openLiveGameCenter;if(typeof open==='function')window.openLiveGameCenter=function(...args){const resume=typeof state!=='undefined'&&!!state.liveGame&&!state.liveGame.finalized;if(resume)emit('live_resume_attempt');try{const value=open.apply(this,args);const modal=document.getElementById('gameSimModal');if(!resume&&modal&&!modal.classList.contains('hidden'))emit('live_started');if(resume)emit(modal&&!modal.classList.contains('hidden')?'live_resumed':'live_resume_failed');return value}catch(error){capture(error,'openLiveGameCenter');throw error}};
 document.addEventListener('click',event=>{const button=event.target?.closest?.('.tab-section-btn[data-key]');if(button)visit(button.dataset.key);const link=event.target?.closest?.('a[href]'),href=link?.getAttribute('href')||'';if(href.startsWith('https://discord.gg/'))emit('community_opened',undefined,undefined,{context:'discord'});else if(href.startsWith('https://www.facebook.com/'))emit('community_opened',undefined,undefined,{context:'facebook'});setTimeout(render,0)});


}
 window.addEventListener('error',event=>capture(event.error||{name:'Error',message:event.message},'global',event));
 window.addEventListener('pagehide',()=>save(true));
 window.addEventListener('unhandledrejection',event=>capture(event.reason,'promise'));
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else if(typeof window.showTab==='function')install();else setTimeout(install,0);
})();

// Build 302: one place that turns internal phase and postseason-context keys into player-facing labels.
// Stored values (state.phase, liveGameContext.type, game-log phase, save summaries) are never changed;
// only the text shown to players goes through these helpers.
(()=>{
'use strict';
const PHASES={
 REGULAR:'Regular Season',PRESEASON:'Preseason',
 CHAMP:'Conference Championships',CONFERENCE:'Conference Championship',CONFERENCE_CHAMP:'Conference Championship',
 POST:'Postseason',POSTSEASON:'Postseason',BOWLS:'Bowl Season',BOWL:'Bowl Game',PLAYOFF:'Playoff',
 AWARDS:'Awards',SIGNING:'Signing Day',SIGNING_DAY:'Signing Day',PORTAL:'Transfer Portal',OFFSEASON:'Offseason'
};
// Only text that looks like a key (ALL_CAPS, snake_case or camelCase with no spaces) is rewritten.
const looksLikeKey=s=>/^[A-Z0-9_]+$/.test(s)||/^[A-Za-z0-9]+(_[A-Za-z0-9]+)+$/.test(s)||/^[a-z]+[A-Z][A-Za-z0-9]*$/.test(s)||/^[a-z]+$/.test(s);
const normal=s=>s.replace(/([a-z0-9])([A-Z])/g,'$1_$2').replace(/[\s-]+/g,'_').toUpperCase();
const words=s=>s.replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/[_-]+/g,' ').trim().toLowerCase().replace(/\b[a-z]/g,c=>c.toUpperCase());
function phaseLabel(key,fallback=''){
 if(key==null||key==='')return fallback;const k=String(key).trim();
 const known=PHASES[normal(k)];if(known)return known;
 return looksLikeKey(k)?words(k):k
}
// "Week 4" during the regular season, otherwise the friendly phase name.
function whenLabel(phase,week){return(phase==null||String(phase).toUpperCase()==='REGULAR')?`Week ${week}`:phaseLabel(phase)}
window.SDF_LABELS302={phase:phaseLabel,when:whenLabel,PHASES};
window.sdfPhaseLabel=phaseLabel;
})();

