function beginYear(){state.postseasonFlow=null;state.liveGameContext=null;state.liveGame=null;state.postseasonApplied242={};ensureV9State();window.SDF_V201?.ensure?.();initializeDepthChart();updateEligibility();state.week=1;state.phase="REGULAR";state.record={w:0,l:0};state.seasonDone=false;state.commits=[];state.scholarships=35;state.signingDayResolved=false;state.lastGameRecap=null;state.recruits=genRecruits(3000);window.SDF_AI_ROSTERS?.ensureAll?.();state.schedule=genSchedule();state.portal=[];state.news=[`Year ${state.year} recruiting opened with the complete ${state.recruits.length}-prospect national class.`];state.standings=schools.filter(s=>s.conference===state.school.conference).map(s=>({id:s.id,name:s.name,w:0,l:0}));state.promises=state.promises.filter(p=>!p.resolved);resetHours()}
// Typical freshman starting ability. Stars describe recruiting reputation;
// scouting can reveal one-tier gems/busts, including both end-of-scale tails.
const FRESHMAN_RECRUIT_OVR_RANGES={1:[55,60],2:[65,71],3:[68,74],4:[74,79],5:[78,82]};
function rollFreshmanRecruitTalent(stars){
 const tier=clamp(Math.round(Number(stars)||1),1,5),roll=(window.SDF_SEEDS?.random()??Math.random());
 const generatedGem=roll<.05,generatedBust=roll>=.05&&roll<.10;
 const range=generatedGem?(tier===5?[83,87]:FRESHMAN_RECRUIT_OVR_RANGES[tier+1]):generatedBust?(tier===1?[50,54]:FRESHMAN_RECRUIT_OVR_RANGES[tier-1]):FRESHMAN_RECRUIT_OVR_RANGES[tier];
 return{ovr:rand(range[0],range[1]),generatedGem,generatedBust}
}
function normalizeSpecialistRecruitStars(r){
 // General recruiting stars use the national scale, not specialist-camp stars.
 // Authored prospects retain the creator's choices; ratings and upside stay intact.
 if(!r||r.created241||!['K','P'].includes(r.pos)||!(Number(r.stars)>3))return false;
 r.stars=3;return true
}
function normalizeSpecialistRecruitClass(){
 let changed=false;
 for(const r of state.recruits||[])changed=normalizeSpecialistRecruitStars(r)||changed;
 for(const r of state.commits||[])changed=normalizeSpecialistRecruitStars(r)||changed;
 if(!changed)return false;
 (state.recruits||[]).sort((a,b)=>b.stars-a.stars||(b.trueOvr||b.ovr)-(a.trueOvr||a.ovr)||String(a.name).localeCompare(String(b.name))).forEach((r,i)=>r.rank=i+1);
 const ranks=new Map((state.recruits||[]).map(r=>[r.id,r.rank]));
 for(const r of state.commits||[])if(ranks.has(r.id))r.rank=ranks.get(r.id);
 return true
}
function genRecruits(n){
 return Array.from({length:n},()=>{
  const roll=(window.SDF_SEEDS?.random()??Math.random()),nationalStars=roll>.98?5:roll>.85?4:roll>.32?3:roll<.10?1:2,p=choice(POSITIONS),st=['K','P'].includes(p)?Math.min(3,nationalStars):nationalStars,l=choice(LOC),interest={};
  const{ovr,generatedGem,generatedBust}=rollFreshmanRecruitTalent(st);
  const priority=choice(["Early playing time","Pro development","Close to home","Winning","NIL opportunity","Academics"]);
  const r={id:(window.SDF_SEEDS?.uuid()??crypto.randomUUID()),name:pname(),pos:p,arch:choice(ARCH[p]),city:l[0],home:l[1],region:l[2],lat:l[3],lon:l[4],stars:st,ovr,pot:0,dev:rollDevelopment(st,ovr),generatedGem,generatedBust,scouted:false,onBoard:false,offered:false,committedTo:null,interest,visit:false,promise:null,priority,personality:choice(["Loyal","Ambitious","Team-first","Competitive","Money-driven","Homesick","Academic","Volatile"]),weeklyPlan:"NONE",stage:"Open",attrs:null,pitchHistory:{},lockedOut:[]};
  r.requirements=recruitRequirements(r);r.dealbreaker=dealbreakerFor(r);return r
 }).sort((a,b)=>b.stars-a.stars||b.ovr-a.ovr).map((r,i)=>{r.rank=i+1;applyHiddenEvaluation(r);relationshipForRecruit(r);normalizeSpecialistRecruitStars(r);return r}).sort((a,b)=>b.stars-a.stars||(b.trueOvr||b.ovr)-(a.trueOvr||a.ovr)).map((r,i)=>{r.rank=i+1;return r})
}
