function coachXPNeeded(){return 85}
function migrateCoachProgress272(){
 const h=state.headCoach;if(!h||h.progressionVersion===272)return;
 const oldLevel=Math.max(1,Math.floor(Number(h.level)||1)),total=(oldLevel-1)*oldLevel*50+Math.max(0,Number(h.xp)||0);
 const newLevel=1+Math.floor(total/coachXPNeeded());
 h.level=newLevel;h.xp=total%coachXPNeeded();h.skillPoints=Math.max(0,Number(h.skillPoints)||0)+Math.max(0,newLevel-oldLevel);h.progressionVersion=272;
}
function coachGameXP(win,type="REGULAR",stage=-1){
 if(type==="PLAYOFF"&&Number(stage)===3)return win?100:20;
 if(type==="PLAYOFF"||type==="CONFERENCE")return win?35:15;
 if(type==="BOWL")return win?30:12;
 return win?18:7;
}
