 while(state.headCoach.xp>=coachXPNeeded()){state.headCoach.xp-=coachXPNeeded();state.headCoach.level++;state.headCoach.skillPoints++;state.news.push(`Head coach reached Level ${state.headCoach.level} and earned a skill point.`)}
