function runSpringPractice(){
 const focuses=["Quarterback Development","Offensive Line Cohesion","Defensive Fundamentals","Conditioning","Youth Development","Scheme Installation","Injury Prevention"];
 $("modalBody").innerHTML=`<span class="eyebrow">SPRING PRACTICE</span><h2>Choose a Team Focus</h2>${focuses.map(f=>`<button class="btn primary full" onclick="selectSpringFocus('${f}')">${f}</button>`).join("")}`;$("modal").classList.remove("hidden")
}
function selectSpringFocus(f){
 state.springFocus=f;state.offseasonTasks.spring=true;
 state.roster.forEach(p=>{let boost=0;if(f==="Quarterback Development"&&p.pos==="QB")boost=2;if(f==="Offensive Line Cohesion"&&["OT","IOL"].includes(p.pos))boost=2;if(f==="Defensive Fundamentals"&&["EDGE","DL","LB","CB","S"].includes(p.pos))boost=1;if(f==="Youth Development"&&p.year<=2)boost=2;if(f==="Conditioning")p.morale=clamp(p.morale+4,0,99);p.ovr=clamp(Math.min(p.pot,p.ovr+boost),45,99)});
 if(f==="Injury Prevention")state.facilities.medical=Math.min(5,state.facilities.medical+.25);
 $("modal").classList.add("hidden");renderOffseasonHub();renderAll()
}
window.selectSpringFocus=selectSpringFocus;
function runPositionBattles(){
 if(state.phase!=='PORTAL'||state.offseasonFlow217?.postPortalBattleComplete)return false;
 window.SDF_V11_TEST?.ensureRealDepth?.();
 const body=$("modalBody"),card=$("modal").querySelector('.modal-card'),scroll=card?.scrollTop||0;
 body.replaceChildren();const title=document.createElement('h2');title.textContent='Position Battles';body.append(title);
 const intro=document.createElement('p');intro.textContent='The transfer portal is closed and the depth chart now starts with the highest-rated eligible players. Review each battle and keep the best OVR choice or select another starter. Changes update your real depth chart and carry into next season.';body.append(intro);
 for(const role of window.SDF_V11_TEST?.ROLE_DEFS||[]){
  const players=state.roster.filter(p=>p.pos===role.pos&&(!p.injury&&window.SDF_DISCIPLINE?.available?.(p)!==false)&&!p.redshirt).sort((a,b)=>b.ovr-a.ovr);if(players.length<2)continue;
  const selected=state.realDepthChart?.[role.key]?.slots?.[0]?.playerId,section=document.createElement('section');section.className='event-card';section.dataset.battleRole=role.key;
  const heading=document.createElement('h3');heading.textContent=role.label;section.append(heading);
  const status=document.createElement('p');status.setAttribute('role','status');status.textContent='Current starter: '+(players.find(p=>p.id===selected)?.name||'Unassigned');section.append(status);
  for(const p of players){const button=document.createElement('button');button.className='btn '+(p.id===selected?'success':'neutral')+' full';button.type='button';button.setAttribute('aria-pressed',String(p.id===selected));button.textContent=`${p.id===selected?'Selected starter ✓ · ':''}${p.name} · OVR ${p.ovr} · ${p.arch}`;button.onclick=()=>window.chooseStarter(role.key,p.id);section.append(button)}
  body.append(section);
 }
 const done=document.createElement('button');done.className='btn success full';done.textContent='Confirm Starters & Finish';done.onclick=()=>window.finishBattles();body.append(done);$("modal").classList.remove('hidden');if(card)card.scrollTop=scroll;
}
function chooseStarter(key,id){
 if(state.phase!=='PORTAL')return false;
 const roles=window.SDF_V11_TEST?.ROLE_DEFS||[],role=roles.find(r=>r.key===key)||roles.find(r=>r.pos===key),p=state.roster.find(p=>p.id===id);
 if(!role||!p||p.pos!==role.pos||p.injury||p.redshirt)return false;
 window.SDF_V11_TEST.ensureRealDepth();const previous=state.realDepthChart[role.key].slots[0].playerId;
 if(previous===id)return false;
 window.setRealDepthPlayer(role.key,0,id);
 state.positionBattleRewards??={};const reward=state.year+':'+id;
 if(!state.positionBattleRewards[reward]){p.morale=clamp(p.morale+5,0,99);state.positionBattleRewards[reward]=true}
 runPositionBattles();window.toast?.(`${p.name} selected as ${role.label} starter.`);window.SDF_RELEASE_TEST?.scheduleSave?.('Position battle starter selected',100,true);return true;
}
function finishBattles(){if(state.phase!=='PORTAL')return false;state.offseasonTasks.battles=true;$("modal").classList.add("hidden");renderOffseasonHub();renderAll();window.toast?.('Position battles complete. Your depth chart selections are saved.')}
window.chooseStarter=chooseStarter;window.finishBattles=finishBattles;
function runPlayerProgression(){
 const top=state.roster.slice().sort((a,b)=>b.pot-b.ovr-(a.pot-a.ovr)).slice(0,18);
 $("modalBody").innerHTML=`<span class="eyebrow">PLAYER DEVELOPMENT</span><h2>Assign Individual Focus</h2>${top.map(p=>`<div class="event-card"><b>${p.name} · ${p.pos} · ${p.ovr}/${p.pot}</b><select onchange="applyPlayerFocus('${p.id}',this.value)"><option value="">Choose focus</option><option>Strength</option><option>Speed</option><option>Awareness</option><option>Technique</option><option>Leadership</option><option>Position Change</option></select></div>`).join("")}<button class="btn success full" onclick="finishProgression()">Finish Development</button>`;$("modal").classList.remove("hidden")
}
function applyPlayerFocus(id,focus){
 const p=state.roster.find(x=>x.id===id);if(!p||!focus)return;p.attrs??=attrsFor(p.pos,p.ovr);
 const staffFocus=Number(window.SDF_V189?.individualFocusBonus?.(p)||0),focusGain=3+staffFocus;if(focus==="Strength")p.attrs.strength=clamp(p.attrs.strength+focusGain,40,99);if(focus==="Speed")p.attrs.speed=clamp(p.attrs.speed+focusGain,40,99);if(focus==="Awareness")p.attrs.awareness=clamp(p.attrs.awareness+focusGain,40,99);if(focus==="Technique")p.attrs.skill=clamp(p.attrs.skill+focusGain,40,99);if(focus==="Leadership")p.morale=clamp(p.morale+7,0,99);
 if(focus==="Position Change"){const map={QB:"WR",RB:"WR",WR:"CB",TE:"OT",OT:"IOL",IOL:"OT",EDGE:"LB",DL:"EDGE",LB:"S",CB:"S",S:"LB"};if(map[p.pos]){p.pos=map[p.pos];p.arch=choice(ARCH[p.pos]);p.ovr=clamp(p.ovr+rand(-4+Math.round(coachEffect("positionChangeBonus")),2+Math.floor(coachEffect("positionChangeBonus")/2)),45,99)}}
}
function finishProgression(){state.offseasonTasks.progression=true;$("modal").classList.add("hidden");autoDepth();renderOffseasonHub();renderAll()}
window.applyPlayerFocus=applyPlayerFocus;window.finishProgression=finishProgression;
function carouselCoachRating(c){return Math.round(avg([Number(c?.recruiting||50),Number(c?.development||50),Number(c?.game||50)]))}
function carouselMoney(v){return "$"+(Number(v||0)>=1000000?(Number(v||0)/1000000).toFixed(2).replace(/0+$/,'').replace(/\.$/,'')+"M":Math.round(Number(v||0)/1000)+"k")}
function carouselProgramPower(s){const w=state.world?.find(t=>Number(t.id)===Number(s.id));return Math.round(Number(w?.rosterPower||((Number(s.prestige||50)+Number(s.recent||50)+Number(s.facilities||50))/3)))}
function carouselConferenceTier(conf){return ({"Great North":5,"Southeastern":5,"Atlantic":5,"Heartland":5,"Western":4,"Metro":3,"Great Lakes":3,"Mountain":3,"Southern Coast":3,"National":3,"Independents":2})[conf]||2}
function carouselCoordinatorCandidates(key,departing){
 const role=key==="oc"?"Offensive Coordinator":"Defensive Coordinator",base=Math.round((state.school.prestige+state.school.recent)/2),styles=key==="oc"?["Recruiting specialist","Quarterback developer","Offensive strategist","Youth developer"]:["Recruiting specialist","Secondary developer","Defensive strategist","Culture builder"];
 return Array.from({length:3},(_,i)=>{const coach=makeCoach(role,base-rand(2,10)+i*2);window.SDF_V189?.decorateCoach?.(coach,role);const rating=carouselCoachRating(coach),specialty=window.SDF_V189?.candidateSpecialtyLabel?.(coach)||styles[(i+state.year)%styles.length],salary=Math.round((260000+rating*8500+i*35000)/10000)*10000,hireCost=Math.round((75000+salary*.18)/10000)*10000;return{coach,specialty,salary,hireCost,fit:rating>=82?"A":rating>=76?"B+":rating>=70?"B":"C+"}})
}
function carouselOfferReason(s,type,performance){
 if(type==="PROMOTION")return `Your ${state.record.w}-win season and rising reputation put you on a bigger program's shortlist.`;
 if(type==="REBUILD")return `${s.name} wants a program builder to restore recent success without starting from zero.`;
 if(performance>=2)return `Strong results above expectations made you a priority candidate.`;
 return `Your recruiting, development and career profile match the program's direction.`
}
function coordinatorCarousel(){
 ensureExpansionState();
 const existing=(state.jobOffers||[]).filter(o=>Number(o.carouselYear)===Number(state.year));if(existing.length&&!state.offseasonTasks.staff){state.jobOffers=existing;renderCarouselModal();return}
 const wins=Number(state.record.w||0),expected=Number(state.seasonExpectations?.expectedWins||state.school.expectation||6),performance=wins-expected,reputation=Number(state.coachCareer.reputation||50),currentPrestige=Number(state.school.prestige||50),currentTier=carouselConferenceTier(state.school.conference),offers=[];
 for(const [key,c] of Object.entries(state.staff||{}).filter(([k])=>k!=="head")){
  const rating=carouselCoachRating(c),staffDeparture=Number(window.SDF_V189?.departureMultiplier?.(c)||1)*Number(window.SDF_V193?.staffDepartureMultiplier?.()||1),chance=clamp((.08+Math.max(0,rating-76)*.018+Math.max(0,wins-8)*.045)*(1-clamp(coachEffect("staffRetentionPct"),0,.55))*staffDeparture,.02,.78);
  if((window.SDF_SEEDS?.random()??Math.random())<chance){const destinations=schools.filter(s=>s.id!==state.school.id&&s.prestige>=state.school.prestige-10).sort((a,b)=>Math.abs(a.prestige-(rating+5))-Math.abs(b.prestige-(rating+5))),destination=choice(destinations.slice(0,12))||choice(schools),retainCost=Math.round(((140000+rating*4200+wins*12000)*(1-clamp(coachEffect("retainCostReduction"),0,.45))*Number(window.SDF_V189?.retainCostMultiplier?.(c)||1))/10000)*10000;offers.push({type:"STAFF_DEPARTURE",carouselYear:state.year,key,coach:c,destination:destination.name,retainCost,status:"PENDING",impact:window.SDF_V189?.departureImpact?.(c)||`${c.role} ratings: Recruiting ${c.recruiting} · Development ${c.development} · Game ${c.game}`})}
 }
 const forcedExit=!!window.SDF_V193?.mustLeaveCurrentJob?.(),jobEligible=forcedExit||wins>=7||reputation>=60||performance>=2;
 if(jobEligible){
  const pool=schools.filter(s=>s.id!==state.school.id).map(s=>{const targetTier=carouselConferenceTier(s.conference),prestige=Number(s.prestige||50),recent=Number(s.recent||50),need=Math.max(0,prestige-recent),delta=prestige-currentPrestige;let jobType=delta>=7||targetTier>currentTier?"PROMOTION":delta<=-7||need>=10?"REBUILD":"LATERAL";let fit=reputation+wins*2.2+performance*4+need*.7-Math.max(0,delta-18)*2+rand(-12,12);const careerFit=window.SDF_V194?.jobFit?.(s,{jobType,need,delta,targetTier,prestige,recent,baseFit:fit,performance,wins})||null;if(careerFit)fit+=Number(careerFit.delta||0);const opening=(need>=6||recent<58||(window.SDF_SEEDS?.random()??Math.random())<.28);return{s,fit,opening,jobType,delta,targetTier,prestige,recent,careerFit}}).filter(x=>x.opening&&x.fit>=72).sort((a,b)=>b.fit-a.fit);
  const desired=wins>=11||reputation>=86?5:wins>=9||reputation>=74?4:Math.max(1,Math.min(3,pool.length));
  const selected=[];for(const type of ["PROMOTION","LATERAL","REBUILD"]){const x=pool.find(p=>p.jobType===type&&!selected.includes(p));if(x)selected.push(x)}for(const x of pool)if(selected.length<desired&&!selected.includes(x))selected.push(x);
  selected.slice(0,desired).forEach(x=>{const s=x.s,power=carouselProgramPower(s),careerFit=x.careerFit||window.SDF_V194?.jobFit?.(s,{jobType:x.jobType})||null,salaryMult=Number(window.SDF_V194?.salaryMultiplier?.(s,{jobType:x.jobType,careerFit})||1),salary=Math.round(((700000+x.prestige*22500+x.targetTier*90000+reputation*6000)*salaryMult)/10000)*10000,years=x.jobType==="REBUILD"?rand(5,7):rand(3,6),security=x.jobType==="REBUILD"?82:x.jobType==="PROMOTION"?62:72,expectedWins=clamp(Math.round((x.prestige+x.recent+power)/28)-1,4,11),reason=window.SDF_V194?.offerReason?.(s,x.jobType,performance,careerFit)||carouselOfferReason(s,x.jobType,performance);offers.push({type:"HEAD_JOB",carouselYear:state.year,school:JSON.parse(JSON.stringify(s)),salary,years,security,expectedWins,jobType:x.jobType,status:"PENDING",reason,programPower:power,careerFit})})
 }
 if(forcedExit&&!offers.some(o=>o.type==="HEAD_JOB")){const fallback=schools.filter(s=>s.id!==state.school.id).sort((a,b)=>a.prestige-b.prestige).slice(0,3);fallback.forEach(s=>offers.push({type:"HEAD_JOB",carouselYear:state.year,school:JSON.parse(JSON.stringify(s)),salary:Math.round((650000+s.prestige*18000)/10000)*10000,years:4,security:78,expectedWins:Math.max(4,Math.round((s.prestige+s.recent)/18)-2),jobType:"REBUILD",status:"PENDING",reason:"After your dismissal, this program is offering a chance to rebuild your coaching career.",programPower:carouselProgramPower(s)}))} state.jobOffers=offers;state.carouselMessage=forcedExit?"Administration dismissed you. Accept a new head-coaching job to continue your career.":offers.length?"Review coordinator decisions and head-coaching opportunities.":"The market was quiet this offseason. Your current job remains available.";renderCarouselModal()
}
function renderCarouselModal(){
 const staffOffers=(state.jobOffers||[]).filter(o=>o.type==="STAFF_DEPARTURE"),headOffers=(state.jobOffers||[]).filter(o=>o.type==="HEAD_JOB"),unresolvedStaff=staffOffers.filter(o=>!["RETAINED","HIRED"].includes(o.status));
 const staffHtml=staffOffers.map((o,i)=>{const idx=state.jobOffers.indexOf(o);if(o.status==="RETAINED")return `<div class="offer-card resolved"><b>${o.coach.name} retained</b><span class="sub">${o.coach.role} returns after a ${carouselMoney(o.retainCost)} raise.</span></div>`;if(o.status==="HIRED")return `<div class="offer-card resolved"><b>${state.staff[o.key]?.name} hired</b><span class="sub">New ${state.staff[o.key]?.role} · ${o.hiredSpecialty||'Balanced staff fit'}</span></div>`;if(o.status==="SEARCH")return `<div class="offer-card"><b>Replace ${o.coach.name} — ${o.coach.role}</b><span class="sub">Choose a candidate. Ratings and one-time hiring cost are shown below.</span>${(o.candidates||[]).map((c,ci)=>`<div class="carousel-candidate"><strong>${c.coach.name} · ${c.fit} fit</strong><span>${c.specialty}</span><small>REC ${c.coach.recruiting} · DEV ${c.coach.development} · GAME ${c.coach.game} · Salary ${carouselMoney(c.salary)}</small><button class="btn primary full" onclick="hireCoordinator(${idx},${ci})" ${state.budget<c.hireCost?'disabled':''}>Hire · ${carouselMoney(c.hireCost)} cost</button></div>`).join('')}<button class="btn neutral full" onclick="promoteAnalyst(${idx})" ${state.budget<75000?'disabled':''}>Promote Analyst · $75k</button>${Number(state.budget||0)<75000?`<p class="muted">You cannot afford a permanent replacement. An internal interim can keep the program running at no hiring cost.</p><button class="btn neutral full" onclick="appointInterimCoordinator(${idx})">Appoint Internal Interim · Free</button>`:''}</div>`;return `<div class="offer-card"><b>${o.coach.name} received a head-coaching offer from ${o.destination}</b><span class="sub">${o.impact}</span><button class="btn primary full" onclick="retainCoordinator(${idx})" ${state.budget<o.retainCost?'disabled':''}>Retain with raise · ${carouselMoney(o.retainCost)}</button><button class="btn neutral full" onclick="letCoordinatorLeave(${idx})">Let Coach Leave & Interview Replacements</button></div>`}).join('')||'<p class="muted">No coordinator departures this offseason.</p>';
 const headHtml=headOffers.map(o=>{const i=state.jobOffers.indexOf(o),resolved=o.status!=="PENDING",careerFit=o.careerFit||window.SDF_V194?.jobFit?.(o.school,{jobType:o.jobType})||null;return `<div class="offer-card ${resolved?'resolved':''}"><div class="carousel-offer-head"><b>${o.jobType}: ${o.school.name}</b><span class="stage">${o.school.conference}</span></div><span class="sub">${o.reason}</span><div class="metric-grid compact">${metric("Program OVR",o.programPower)}${metric("Prestige",o.school.prestige)}${metric("Recent",o.school.recent)}${metric("Expected Wins",o.expectedWins)}${metric("Contract",`${o.years} years`)}${metric("Starting Security",`${o.security}%`)}${careerFit?metric("Career Fit",`${careerFit.score} · ${careerFit.label}`):''}</div>${careerFit?`<span class="sub">What they value: ${careerFit.priority} · Career Loyalty ${careerFit.loyalty}</span>`:''}<span class="sub">Salary ${carouselMoney(o.salary)} · ${o.status==='DECLINED'?'Declined':o.status==='ACCEPTED'?'Accepted':'Decision pending'}</span>${resolved?'':`<button class="btn primary full" onclick="acceptJob(${i})" ${window.SDF_SCENARIOS?.canChangeSchools(state)===false?'disabled title="End your scenario before changing schools"':''}>${window.SDF_SCENARIOS?.canChangeSchools(state)===false?'Scenario · School Locked':'Accept Job'}</button><button class="btn neutral full" onclick="declineJob(${i})">Decline</button>`}</div>`}).join('')||'<p class="muted">No head-coaching offers matched your current profile.</p>';
 $("modalBody").innerHTML=`<span class="eyebrow">COACHING CAROUSEL</span><h2>Staff & Job Market</h2><p class="muted">${state.carouselMessage||''}</p><div class="metric-grid">${metric("Current School",state.school.name)}${metric("Season Record",`${state.record.w}-${state.record.l}`)}${metric("Coach Reputation",state.coachCareer.reputation)}${metric("Program Prestige",state.school.prestige)}${metric("Athletics Budget",carouselMoney(state.budget))}</div><h3>Coordinator Market</h3>${staffHtml}<h3>Head-Coaching Opportunities</h3>${headHtml}${window.SDF_V193?.mustLeaveCurrentJob?.()?`<div class="carousel-stay danger"><b>Current job unavailable</b><span class="sub">Administration has dismissed you. Accept one of the head-coaching opportunities above.</span></div>`:`<div class="carousel-stay"><b>Stay at ${state.school.name}</b><span class="sub">Declining or ignoring head jobs keeps your coach and program-building progress here.</span></div>`}${unresolvedStaff.length?`<p class="warning-text">Resolve ${unresolvedStaff.length} coordinator decision${unresolvedStaff.length===1?'':'s'} before finishing.</p>`:''}<button class="btn success full" onclick="finishCarousel()" ${unresolvedStaff.length||window.SDF_V193?.mustLeaveCurrentJob?.()?'disabled':''}>${window.SDF_V193?.mustLeaveCurrentJob?.()?'Accept a New Job Above':'Stay / Finish Carousel'}</button>`;$("modal").classList.remove("hidden");window.SDF_V217_OFFSEASON?.addStaffButton?.("staff")
}
