['textSizeSetting','densitySetting','motionSetting'].forEach(id=>$(id).onchange=applySettings);loadSettings();
$('saveSlotPicker').onchange=async()=>{if(!state.school){renderSaveManager();return}let slot=$('saveSlotPicker').value;if(String(state.saveSlot)!==String(slot)){if(confirm(`Return to the dynasty menu and select Slot ${slot}? Your current dynasty will autosave first.`)){if(await saveNow('Changed slot',false,false))location.reload();else $('saveSlotPicker').value=state.saveSlot}else $('saveSlotPicker').value=state.saveSlot}};
document.addEventListener('change',()=>scheduleSave('Changed setting',700));document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!state.school)return;if(b.matches('.nav-tab,[data-mobile-target],[data-sdf-help],#mobileMoreBtn,#closeModal,#closeGameSim'))return;setTimeout(()=>scheduleSave('Action',850),0)});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveNow('Background save',false,false)});window.addEventListener('pagehide',()=>saveNow('Exit save',false,false));setInterval(()=>{if(state.school&&Date.now()-lastSaveAt>45000)scheduleSave('Periodic save',120)},45000);
