function restoreFeedAnchor296(host,owner,anchor){const row=[...host.children].find(r=>r.dataset.feedKey===anchor.key);if(!row)return;if(owner===host)host.scrollTop=row.offsetTop-anchor.offset;else owner.scrollTop+=row.getBoundingClientRect().top-anchor.top}
