  PUNTING:[['G',s.games],['PUNTS',s.punts],['YDS',s.puntYds],['AVG',s.punts?(s.puntYds/s.punts).toFixed(1):'0.0'],['LONG',s.puntLong],['IN 20',s.inside20]],
