 const entry={at:new Date().toISOString(),stage,placement:attempt?.kind?'reward_'+attempt.kind.toLowerCase():'season_end',attempt:attempt?.id||null,test:!!cfg().useTestAds,detail:String(detail?.message||detail||'').slice(0,250)};
 adAudit.push(entry);adAudit=adAudit.slice(-200);
