 const userPass=avg([qb?grade(qb,['accuracy','throwPower','decision']):60,...rec.map(p=>grade(p,['routeRunning','hands','speed','release']))]),oppCoverage=opponentGrade(g,'coverage'),passEdge=userPass-oppCoverage;
