function gameResultHtml(g){if(!g)return'';const aSeed=seedOf(g.a),bSeed=seedOf(g.b),a=`${aSeed<99?'#'+aSeed+' ':''}${g.a.name}`,b=`${bSeed<99?'#'+bSeed+' ':''}${g.b.name}`;return`<div class="bracket-card ${Number(g.winner?.id)===Number(state.school.id)?'champion-card':''}"><b>${a} ${g.aScore}</b><br><b>${b} ${g.bScore}</b><span class="sub">Winner: ${g.winner.name}</span></div>`}
function pendingGameHtml(pair,result,label){if(result)return gameResultHtml(result);const a=pair?.[0],b=pair?.[1];if(!a||!b)return'';const user=pair.some(t=>Number(t.id)===Number(state.school.id));return`<div class="bracket-card ${user?'champion-card':''}"><span class="eyebrow">${user?'YOUR GAME':'UPCOMING'}</span><b>#${seedOf(a)} ${a.name}</b><br><b>#${seedOf(b)} ${b.name}</b><span class="sub">${label}</span></div>`}
const roundNames=['CFP First Round','CFP Quarterfinal','CFP Semifinal','National Championship'];
function pairsFor(stage,prev=[]){const f=state.postseasonData.playoffField||[];if(stage===0)return[[f[4],f[11]],[f[5],f[10]],[f[6],f[9]],[f[7],f[8]]].filter(x=>x[0]&&x[1]);if(stage===1)return[[f[0],prev[3]],[f[3],prev[0]],[f[1],prev[2]],[f[2],prev[1]]].filter(x=>x[0]&&x[1]);if(stage===2)return[[prev[0],prev[1]],[prev[2],prev[3]]].filter(x=>x[0]&&x[1]);return prev.length>=2?[[prev[0],prev[1]]]:[]}
function postseasonSnapshotHtml(){const d=state.postseasonData;if(!d)return'';const f=d.playoffField||[];let html=`<div class="playoff-round"><h3>12-Team CFP Field</h3><div class="playoff-matchups">${f.map(t=>`<div class="bracket-card"><b>#${t.seed} ${t.name}</b><span class="sub">${t.record?.w??0}-${t.record?.l??0}${t.seed<=4?' · First-round bye':''}</span></div>`).join('')}</div></div>`;for(let stage=0;stage<4;stage++){const saved=d.playoffRounds?.[stage],flow=state.postseasonFlow?.mode==='PLAYOFF'&&state.postseasonFlow.stage===stage?state.postseasonFlow:null;if(!saved&&!flow)continue;const pairs=flow?.pairs||[],results=flow?.results||[],cards=saved?saved.games.map(gameResultHtml).join(''):pairs.map((pair,i)=>pendingGameHtml(pair,results[i],roundNames[stage])).join('');html+=`<div class="playoff-round"><h3>${roundNames[stage]}</h3><div class="playoff-matchups">${cards||'<p class="muted">Matchups pending.</p>'}</div></div>`}if(d.nationalChampion)html+=`<div class="bracket-card champion-card"><span class="eyebrow">NATIONAL CHAMPION</span><h3>${d.nationalChampion.name}</h3></div>`;return html}
const baseRenderPostseasonBrackets=window.renderPostseasonBrackets;
window.renderPostseasonBrackets=function(){const d=state.postseasonData;if(!d)return;try{baseRenderPostseasonBrackets?.()}catch{}const bowls=$16('bowlGames'),bracket=$16('fullPlayoffBracket');if(bowls){const results=d.bowlResults||[];bowls.innerHTML=(d.bowls||[]).map(b=>{const r=results.find(x=>x.label===b.name&&((x.a.id===b.a.id&&x.b.id===b.b.id)||(x.a.id===b.b.id&&x.b.id===b.a.id)));return r?gameResultHtml(r):`<div class="bracket-card"><span class="eyebrow">${b.name}</span><h3>${b.a.name} vs ${b.b.name}</h3></div>`}).join('')}if(bracket)bracket.innerHTML=postseasonSnapshotHtml()}
function resumePostseason(){
 if(state.liveGameContext){window.showTab('gameday');window.openLiveGameCenter();return true}
 const f=state.postseasonFlow,d=state.postseasonData;
 if(f?.pendingAdvance||f?.stageComplete){continuePostseasonFlow();return true}
 if(f?.mode==='PLAYOFF'&&f.pairs?.[f.userIndex]){setLive('PLAYOFF',roundNames[f.stage],f.pairs[f.userIndex],{stage:f.stage,userIndex:f.userIndex});return true}
 if(d?.nationalChampion){finishSeason();return true}
 if(state.phase==='CHAMP'&&d?.conferenceResults?.some(g=>[g.a?.id,g.b?.id].some(id=>Number(id)===Number(state.school.id)))){prepareBowlsAndPlayoff();return true}
 // Older saves may have completed rounds but no pending-flow marker. Resume after the last recorded round.
 const rounds=d?.playoffRounds||[],last=rounds.reduce((best,x,i)=>x?.games?.length?i:best,-1);
 if(state.phase==='BOWLS'&&last>=0){const games=rounds[last].games,winners=games.map(g=>g.winner);if(last===3){d.nationalChampion=winners[0];finishSeason()}else if(winners.some(t=>Number(t.id)===Number(state.school.id))||(last===0&&seedOf(state.school)<=4)){runPlayoffStage(last+1,winners)}else{simulateRemainingFrom(last+1,winners);finishSeason()}return true}
 const bowl=d?.bowlResults?.find(g=>[g.a?.id,g.b?.id].some(id=>Number(id)===Number(state.school.id)));if(state.phase==='BOWLS'&&bowl){simulatePlayoffWithoutUser();finishSeason();return true}
 return false
}
function startChampionship(){if(state.phase!=='CHAMP')return;if(resumePostseason())return;const games=state.postseasonData.conferenceGames||[],user=games.find(x=>[x.a.id,x.b.id].includes(state.school.id));state.postseasonData.conferenceResults=games.filter(x=>x!==user).map(x=>simulateNeutralGame(x.a,x.b,`${x.conference} Championship`));if(!user){state.postseasonData.champions=state.postseasonData.conferenceResults.map(x=>x.winner);prepareBowlsAndPlayoff();return}showBid(`${state.school.conference} Championship: ${state.school.name} vs ${(user.a.id===state.school.id?user.b:user.a).name}`);setLive('CONFERENCE',`${user.conference} Championship`,[user.a,user.b],{conference:user.conference})}
function completeConference(ctx,game){const pair=ctx.meta.pair,result=liveResult(pair,ctx.label,game);state.postseasonData.conferenceResults.push(result);state.postseasonData.champions=state.postseasonData.conferenceResults.map(x=>x.winner);if(result.winner.id===state.school.id){state.achievementStats.conferenceTitles++;state.conferenceChampions.push({year:state.year,conference:state.school.conference});state.trophies.push({year:state.year,type:`${state.school.conference} Champion`})}updateRankings();state.postseasonFlow={mode:'CONFERENCE_COMPLETE',result,pendingAdvance:true}}
