function ensureSnapDraft(role){if(!snapDrafts[role])snapDrafts[role]=snapValues(role);return snapDrafts[role]}
window.setRealDepthPlayer=function(role,index,id){window.SDF_V11_TEST?.ensureRealDepth?.();const defs=window.SDF_V11_TEST?.ROLE_DEFS||[],def=defs.find(r=>r.key===role),slots=state.realDepthChart?.[role]?.slots;if(!def||!slots?.[index])return;if(id){defs.filter(r=>r.pos===def.pos).forEach(r=>(state.realDepthChart?.[r.key]?.slots||[]).forEach((slot,i)=>{if(!(r.key===role&&i===index)&&slot.playerId===id)slot.playerId=''}))}slots[index].playerId=id;window.SDF_V11_TEST?.ensureRealDepth?.();window.renderDepthManager?.();saveNow('Depth chart updated')};
function rebalanceSnapDraft(role,index,value){const slots=state.realDepthChart?.[role]?.slots||[],draft=ensureSnapDraft(role);if(index<0||index>=draft.length)return;const next=clamp(Math.round(num(value)),0,100),others=draft.map((v,i)=>({i,value:Math.max(0,num(v)),active:!!slots[i]?.playerId})).filter(x=>x.i!==index),eligible=others.filter(x=>x.active);draft[index]=next;if(!eligible.length){others.forEach(x=>draft[x.i]=0);return}const remaining=100-next,weight=eligible.reduce((n,x)=>n+x.value,0);let used=0;eligible.forEach((x,i)=>{const share=i===eligible.length-1?remaining-used:Math.round(remaining*(weight?x.value/weight:1/eligible.length));draft[x.i]=clamp(share,0,remaining-used);used+=draft[x.i]});others.filter(x=>!x.active).forEach(x=>draft[x.i]=0)}
