window.runPlayerProgression=function(){developmentReturn=null;const top=state.roster.slice().sort((a,b)=>(b.pot-b.ovr)-(a.pot-a.ovr)).slice(0,18);el('modalBody').innerHTML=`<span class="eyebrow" data-development-list>PLAYER DEVELOPMENT</span><h2>Assign Individual Focus</h2><p class="muted"><b>OVR</b> is current ability. <b>Potential</b> is the player’s ceiling. Focuses improve specific attributes and do not replace normal offseason progression.</p>${top.map(p=>`<div class="event-card development-player-card"><div><b>${esc(p.name)} · ${p.pos}</b><span class="sub">OVR ${p.ovr} · Potential ${p.pot} · ${p.dev} development</span></div><button class="btn neutral small" onclick="openDevelopmentPreview('${p.id}')">Player Preview</button><select onchange="applyPlayerFocus('${p.id}',this.value)"><option value="">Choose focus</option>${Object.keys(focusText).map(f=>`<option value="${f==='PositionChange'?'Position Change':f}">${f==='PositionChange'?'Position Change':f} — ${focusText[f]}</option>`).join('')}</select></div>`).join('')}<button class="btn success full" onclick="finishProgression()">Finish Development</button>`;el('modal').classList.remove('hidden')};

// Coach identity and career follow the coach, while program history follows each school.
// Coach identity now comes from the Create Your Coach popup on the team screen.
function beforeStart163(){const pending=window.SDF_NEW_DYNASTY_PENDING;return{name:(pending?.coachName||state.coachCareer?.name||'Coach').trim()||'Coach'}}
function afterStart163(context,result){
 if(!state.school)return result;const name=context?.name||'Coach';state.coachCareer.name=name;state.staff?.head&&(state.staff.head.name=name);state.coachCareer.currentSchoolId=state.school.id;state.coachCareer.currentSchool=state.school.name;state.coachCareer.currentStintStart=state.year;ensureRepairState();captureProgramBaseline();saveNow('Coach career created',false,true);return result
}
function beforeAcceptJob163(){if(!state.school)return null;return{id:state.school.id,name:state.school.name,conference:state.school.conference,start:state.coachCareer.currentStintStart||1,end:state.year,record:`${state.coachCareer.careerWins}-${state.coachCareer.careerLosses}`}}
