function schemeFitTier(score){
 return score>=90?{label:'Perfect',bonus:3}:score>=78?{label:'Good',bonus:1}:score>=65?{label:'Neutral',bonus:0}:score>=50?{label:'Poor',bonus:-2}:{label:'Terrible',bonus:-4};
}
function playerSchemeFit(p){
 const offense=['QB','RB','WR','TE','OT','IOL'].includes(p.pos),scheme=offense?state.offense:state.defense;
 const table=offense?(OFF_SCHEME_FITS[scheme]||OFF_SCHEME_FITS.Spread):(DEF_SCHEME_FITS[scheme]||DEF_SCHEME_FITS.Multiple);
 const ideal=table?.[p.pos]||[],normalize=x=>String(x||'').toLowerCase().replace('pass coverage','coverage').replace('physical','possession').replace('power rusher','power').replace('pass rusher','power').replace('run blocker','power').replace('vertical threat','vertical');
 const arch=normalize(p.arch);if(!arch||!ideal.length)return 70;
 const index=ideal.findIndex(x=>arch.includes(normalize(x))||normalize(x).includes(arch));
 const known=(typeof ARCH==='object'?ARCH[p.pos]:[])||[];
 if(index<0&&!known.some(x=>normalize(x)===arch))return 70;
 let score=index===0?94:index>=1?82:60;
 // A stationary QB in an option offense is an especially costly mismatch.
 if(scheme==='Option'&&p.pos==='QB'&&arch==='field general')score=45;
 const awareness=n(p.attrs?.awareness,p.ovr),relative=awareness-n(p.ovr,awareness);
 score+=clamp(Math.round(relative/8),-3,3);return clamp(score,40,99);
}
function schemeFitBonus(side){
 const positions=side==='offense'?['QB','RB','WR','TE','OT','IOL']:['EDGE','DL','LB','CB','S'];
 const active=(state.roster||[]).filter(p=>positions.includes(p.pos)&&p.starter&&(!p.injury&&window.SDF_DISCIPLINE?.available?.(p)!==false)&&!p.redshirt&&state.playerEligibility?.[p.id]!==false);
 const fitBonus=active.length?active.reduce((sum,p)=>sum+schemeFitTier(playerSchemeFit(p)).bonus,0)/active.length:0;
 const staffBonus=Number(window.SDF_V189?.schemeCoordinatorBonus?.(side)||0);
 return clamp(Math.round(fitBonus+staffBonus),-4,5);
}
function renderSchemeFit(){
 const host=el('schemeFitV170');if(!host)return;const rows=(state.roster||[]).filter(p=>p.starter&&(!p.injury&&window.SDF_DISCIPLINE?.available?.(p)!==false)&&!p.redshirt).map(p=>({p,fit:playerSchemeFit(p)})).sort((a,b)=>b.fit-a.fit),avgFit=rows.length?Math.round(rows.reduce((s,x)=>s+x.fit,0)/rows.length):70;
 host.innerHTML=`<div class="section-head"><div><span class="eyebrow">SCHEME FIT</span><h2>${esc(state.offense)} / ${esc(state.defense)}</h2><p class="muted">Ratings remain the biggest factor. Scheme fit adjusts team performance using eligible starters: Perfect +3, Good +1, Neutral 0, Poor −2, Terrible −4. These are averaged, with coordinator support, rather than added per player.</p></div><span class="viz-badge">${avgFit} average fit</span></div><div class="metric-grid">${metric('Offense Bonus',`${schemeFitBonus('offense')>=0?'+':''}${schemeFitBonus('offense')} OVR`)}${metric('Defense Bonus',`${schemeFitBonus('defense')>=0?'+':''}${schemeFitBonus('defense')} OVR`)}</div><div class="two-col"><div><h3>Best Fits</h3>${rows.slice(0,5).map(x=>`<div class="event-card"><b>${esc(x.p.name)} · ${x.p.pos}</b><span>${schemeFitTier(x.fit).label} · ${x.fit} fit · ${schemeFitTier(x.fit).bonus>0?'+':''}${schemeFitTier(x.fit).bonus}</span></div>`).join('')}</div><div><h3>Needs Adjustment</h3>${rows.slice(-5).reverse().map(x=>`<div class="event-card"><b>${esc(x.p.name)} · ${x.p.pos}</b><span>${schemeFitTier(x.fit).label} · ${x.fit} fit · ${schemeFitTier(x.fit).bonus>0?'+':''}${schemeFitTier(x.fit).bonus}</span></div>`).join('')}</div></div>`;
}

