 const rb=n(s.rushYds)/8+n(s.rushTD)*8+n(s.recYds)/14+n(s.recTD)*6+n(s.rec)*.25+brand+teamBonus;
 const rec=n(s.recYds)/8+n(s.recTD)*8+n(s.rec)*.45+n(s.rushYds)/18+n(s.rushTD)*5+brand+teamBonus;
 const def=n(s.tackles)*1.35+n(s.tfl)*3+n(s.sacks)*8+n(s.defINT)*12+n(s.ff)*7+brand+teamBonus;
 const front=n(s.tackles)*1.2+n(s.tfl)*3.4+n(s.sacks)*9+n(s.defINT)*8+n(s.ff)*7+brand+teamBonus;
 const db=n(s.tackles)*1.1+n(s.tfl)*2+n(s.sacks)*4+n(s.defINT)*15+n(s.ff)*7+brand+teamBonus;
 const kick=n(s.points)*1.5+n(s.fgm)*3-(Math.max(0,n(s.fga)-n(s.fgm))*4)+(n(s.fga)?n(s.fgm)/n(s.fga)*25:0)+brand+teamBonus;
 const punt=(n(s.punts)?n(s.puntYds)/n(s.punts):0)*2+n(s.inside20)*5+n(s.puntLong)*.3-n(s.touchbacks)*2+brand+teamBonus;
 if(type==='QB')return qb;if(type==='RB')return rb;if(type==='REC')return rec;if(type==='DEFENSE')return def;if(type==='FRONT7')return front;if(type==='DB')return db;if(type==='K')return kick;if(type==='P')return punt;
