function applyAdPolicy(){
 const remove=owns('remove_ads');
 const policy=window.SDF_AD_POLICY||{};
 policy.shouldShowForcedAds=()=>!remove;
 policy.mayOfferRewardedAds=()=>true;
 policy.canUseRewardedAds=()=>true;
 window.SDF_AD_POLICY=policy;
 document.documentElement.classList.toggle('sdf-no-forced-ads',remove);
 window.SDF_MONETIZATION?.render?.();
}
function normalizeState(next){
 if(!next||typeof next!=='object')return;
 billing={ready:!!next.ready,status:String(next.status||'Google Play Billing'),owned:Array.isArray(next.owned)?next.owned:[],prices:next.prices&&typeof next.prices==='object'?next.prices:{},consumables:next.consumables&&typeof next.consumables==='object'?next.consumables:{}};
 if(pendingProduct){const status=billing.status;const outcome=/cancel/i.test(status)?'checkout_canceled':/pending/i.test(status)?'checkout_pending':/error|unavailable|could not|not available|No eligible/i.test(status)?'checkout_failed':null;if(outcome&&outcome!==lastOutcome){window.SDF_JOURNEY?.record(outcome,pendingProduct);lastOutcome=outcome;if(outcome!=='checkout_pending'){pendingProduct=null;savePendingCheckout();}}}
 applyAdPolicy();window.SDF_PREMIUM251?.claimPending?.();renderShop();updateButtons();
 window.dispatchEvent(new CustomEvent('sdf:play-entitlements',{detail:{...billing}}));
}
// Ownership refreshes/restores are entitlements, not evidence of a new sale.
window.onSDFPurchaseCompleted=receipt=>{
 if(!pendingProduct||receipt?.product!==pendingProduct||!Number.isFinite(Number(receipt.purchasedAt))||Number(receipt.purchasedAt)<pendingStartedAt-5000)return;
 window.SDF_JOURNEY?.record('purchase_confirmed',pendingProduct);lastOutcome='purchase_confirmed';pendingProduct=null;savePendingCheckout();
 window.dispatchEvent(new CustomEvent('sdf:play-purchase-completed',{detail:{product:receipt.product,purchasedAt:Number(receipt.purchasedAt)}}));
};
window.onSDFBillingState=normalizeState;
function refreshBilling(){try{const n=native();if(!n)return normalizeState({ready:false,status:storeText('Google Play Billing is available only in the installed Android app.','Purchases are available in the installed Android app. Browser play includes everything free in the game.'),owned:[],prices:{}});normalizeState(JSON.parse(n.getState()||'{}'))}catch(err){console.warn('Play Billing state unavailable',err)}}

function ensureShop(){if($p('#sdfPlayShop'))return;const o=document.createElement('div');o.id='sdfPlayShop';o.innerHTML=`<section class="sdf-premium-box"><header class="sdf-premium-head"><div><div class="sdf-premium-ey">${storeText('GOOGLE PLAY · PERMANENT UPGRADES','PERMANENT UPGRADES')}</div><h2>Dynasty Shop</h2><p>${storeText('One-time purchases restore through the Google account used by Play Store.','One-time purchases are made in the Android app and restore to the account that bought them.')}</p></div><button class="sdf-premium-close" aria-label="Close">×</button></header><div class="sdf-premium-body"><div id="sdfPlayStatus" class="sdf-play-status"></div><div class="sdf-shop-intro"><b>Commissioner Mode unlocks the complete toolbox.</b><p>Edit players and every program, create teams and recruits, remove forced ads, and receive future Commissioner tools.</p></div><button type="button" class="journey-preview-entry" id="sdfCommissionerPreview">Try an interactive Commissioner Mode sample</button><div id="sdfPlayProducts" class="sdf-product-grid"></div><button id="sdfRestorePurchases" class="sdf-restore">${storeText('Restore Google Play Purchases','Restore Purchases')}</button></div></section>`;document.body.append(o);$p('#sdfCommissionerPreview').onclick=()=>window.SDF_JOURNEY?.openPreview();$p('.sdf-premium-close',o).onclick=closeShop;o.onclick=e=>{if(e.target===o)closeShop()};$p('#sdfRestorePurchases').onclick=()=>{const n=native();if(n){n.restore();setShopStatus('Checking your Google Play account…')}else setShopStatus(storeText('Google Play Billing is unavailable in this build.','Purchases can be restored in the Android app.'),true)}}
function setShopStatus(t,bad=false){const x=$p('#sdfPlayStatus');if(!x)return;x.textContent=t;x.className='sdf-play-status '+(bad?'bad':billing.ready?'good':'')}
let shopFocus=null;
function renderShop(){const grid=$p('#sdfPlayProducts');if(!grid)return;setShopStatus(billing.status,!billing.ready&&/error|unavailable|could not/i.test(billing.status));grid.innerHTML='';for(const [k,n,fallback,d,badge,features=[],saving='',type='permanent'] of PRODUCTS){const repeat=type==='consumable',own=!repeat&&owns(k),card=document.createElement('article');card.dataset.product=k;card.dataset.productType=type;card.className='sdf-product'+(k==='commissioner_mode'?' featured':'')+(shopFocus===k?' focused':'');card.innerHTML=`${badge?`<span class="sdf-product-badge">${badge}</span>`:''}<h3>${n}</h3><div><span class="sdf-product-price">${esc(price(k,fallback))}</span> <span class="sdf-product-once">${repeat?'REPEATABLE':'ONE-TIME'}</span></div><p>${esc(d)}</p>${features.length?`<ul class="sdf-product-list">${features.map(x=>`<li>${esc(storeFeature(x))}</li>`).join('')}</ul>`:''}${saving?`<span class="sdf-product-saving">${esc(saving)}</span>`:''}<button ${own?'disabled':''}>${own?'OWNED':`BUY ${esc(price(k,fallback))}`}</button>${own?`<div class="sdf-owned">${storeText('✓ Google Play account unlock','✓ Unlocked')}</div>`:''}`;card.querySelector('button').onclick=()=>purchase(k);grid.append(card)}}
function openShop(focus=null){shopFocus=PRODUCTS.some(x=>x[0]===focus)?focus:null;window.SDF_JOURNEY?.record('shop_opened',shopFocus||undefined);ensureShop();refreshBilling();$p('#sdfPlayShop').classList.add('open');renderShop();if(shopFocus)setTimeout(()=>$p(`[data-product="${shopFocus}"]`)?.scrollIntoView?.({block:'center'}),0)}
function closeShop(){$p('#sdfPlayShop')?.classList.remove('open')}
function purchase(k){if(!CONSUMABLES.has(k)&&owns(k))return;const n=native();if(!n)return setShopStatus(storeText('Google Play Billing is unavailable in this build.','Purchases are available in the Android app.'),true);if(CONSUMABLES.has(k)&&!window.SDF_PREMIUM251?.canReceiveBoost?.())return setShopStatus('Load a dynasty before purchasing a resource boost.',true);pendingProduct=k;pendingStartedAt=Date.now();lastOutcome=null;savePendingCheckout();window.SDF_JOURNEY?.record('checkout_started',k);setShopStatus('Opening Google Play checkout…');try{n.purchase(k)}catch{pendingProduct=null;savePendingCheckout();window.SDF_JOURNEY?.record('checkout_failed',k);setShopStatus('Could not open Google Play checkout. Please try again.',true)}}

function ensureEditor(){if($p('#sdfAndroidEditor'))return;const o=document.createElement('div');o.id='sdfAndroidEditor';o.innerHTML=`<section class="sdf-premium-box"><header class="sdf-premium-head"><div><div class="sdf-premium-ey">COMMISSIONER TOOLS</div><h2 id="sdfEditorTitle"></h2><p id="sdfEditorSubtitle"></p></div><button class="sdf-premium-close" aria-label="Close">×</button></header><div class="sdf-premium-body"><div id="sdfEditorToast" class="sdf-editor-toast"></div><div id="sdfEditorContent"></div></div></section>`;document.body.append(o);$p('.sdf-premium-close',o).onclick=closeEditor;o.onclick=e=>{if(e.target===o)closeEditor()}}
