function decoratePreview(kind){if(!editorPreview)return;const body=$p('#sdfEditorContent');if(!body)return;let bar=$p('.sdf-preview-bar',body);if(!bar){bar=document.createElement('div');bar.className='sdf-preview-bar';body.prepend(bar)}bar.innerHTML=`<b>READ-ONLY PREVIEW · SAME CONTROLS AS THE FULL EDITOR</b><button data-preview-kind="player" class="${kind==='player'?'active':''}">Player Editor</button><button data-preview-kind="team" class="${kind==='team'?'active':''}">Team Editor</button><button data-preview-kind="conference" class="${kind==='conference'?'active':''}">Conferences</button><button class="buy">View Commissioner Mode</button>`;bar.querySelectorAll('[data-preview-kind]').forEach(b=>b.onclick=()=>openExactPreview(b.dataset.previewKind));bar.querySelector('.buy').onclick=()=>{editorPreview=false;work=null;$p('#sdfAndroidEditor')?.classList.remove('open');openShop('commissioner_mode')};lockPreviewControls()}
