function rosterAction(type){const s=current();if(!playerRoster292(s).length)return;let changed=0;if(type==='heal'){for(const p of playerRoster292(s))if(p.injury){p.injury=null;changed++}}else if(type==='morale'){for(const p of playerRoster292(s))if(Number(p.morale)<70){p.morale=70;changed++}}else if(type==='overall'){for(const p of playerRoster292(s)){const before=Number(p.ovr);p.ovr=clamp(before+1,40,99);p.pot=Math.max(p.ovr,Number(p.pot));changed+=p.ovr!==before}}else if(type==='potential'){for(const p of playerRoster292(s)){const before=Number(p.pot);p.pot=clamp(before+3,40,99);changed+=p.pot!==before}}if(!changed)return editorToast('No roster values needed an update.');if(commit(`Player Editor bulk ${type} update`)){openPlayerEditor(activePlayerId,true);setTimeout(()=>editorToast(`${changed} player${changed===1?'':'s'} updated.`),0)}}
