function promiseForecast(promise,player,override={}){normalizePromise(promise);const d=defFor(promise),raw=state.playerUsageV188?.[player.id]||{},assigned=assignedUsage(player),snap=clip(override.snap??assigned.snap,0,100),starter=override.starter??assigned.starter,played=Number(raw.games||0),remaining=remainingScheduledGames(),games=played+remaining,starts=Number(raw.starts||0)+(starter?remaining:0),snapTotal=Number(raw.snapTotal||0)+snap*remaining,forecast={games,starts,avgSnap:games?snapTotal/games:snap};let onTrack=true;if(d.evaluate)onTrack=!!d.evaluate(player,forecast,promise);return{onTrack,forecast,current:usageFor(player.id),assigned:{snap,starter:!!starter},remaining}}
