function recordCompletedUsage(){if(!state?.school||state.phase==='PORTAL')return;const recorded=new Set(state.usageRecordedWeeksV188||[]);for(const g of state.schedule||[]){if(!g?.result)continue;const key=`${state.year}-${g.week}`;if(recorded.has(key))continue;for(const p of state.roster||[]){const current=assignedUsage(p),u=state.playerUsageV188[p.id]||{year:state.year,games:0,starts:0,snapTotal:0};if(Number(u.year)!==Number(state.year)){u.year=state.year;u.games=0;u.starts=0;u.snapTotal=0}u.games++;u.starts+=current.starter?1:0;u.snapTotal+=current.snap;state.playerUsageV188[p.id]=u;let trustDelta=current.starter?.45:current.snap>=25?.18:current.snap<10&&['Competitive','Ambitious','Volatile'].includes(p.personality)?-.55:-.12;if(['Loyal','Team-first'].includes(p.personality)&&trustDelta<0)trustDelta*=.45;p.trust=clip(Number(p.trust??trustDefault(p))+trustDelta,0,100)}recorded.add(key)}state.usageRecordedWeeksV188=[...recorded].slice(-30)}
