 p.ambition=Math.round(clip(p.ambition??opts.ambition??(42+hash(seed+'-amb')%50),20,96));
 p.loyalty=Math.round(clip(p.loyalty??opts.loyalty??(40+hash(seed+'-loy')%51),20,98));
 p.relationship=Math.round(clip(p.relationship??opts.relationship??(55+hash(seed+'-rel')%31),25,99));
