function ensure(){if(!state?.school)return;const legacy=!state._traditionMigrationV190&&Array.isArray(state.traditions)?state.traditions.slice():[];state.programIdentityVersion=BUILD;state.traditionProgressV190??={};state.programIdentityV190??={focus:identityDefault(),selectedYear:null,history:[]};if(!IDENTITY_DEFS[state.programIdentityV190.focus])state.programIdentityV190.focus=identityDefault();for(const key of Object.keys(TRADITION_DEFS)){const row=state.traditionProgressV190[key]??={score:0,tier:0,unlockedYear:null};const next=Math.max(Number(row.score||0),Math.round(targetScore(key)));row.score=clip(next,0,100);row.tier=tierFor(row.score);if(row.tier>0&&row.unlockedYear==null)row.unlockedYear=Number(state.year||1)}if(legacy.length){for(const old of legacy){const key=LEGACY_MAP[old?.name];if(!key)continue;const row=state.traditionProgressV190[key];row.score=Math.max(row.score,old.name==='Sleeping Giant'?30:45);row.tier=tierFor(row.score)}}state._traditionMigrationV190=1;syncLegacyTraditions();}
function syncLegacyTraditions(){const active=activeTraditions();state.traditions=active.map(x=>({key:x.key,name:x.name,desc:`${x.tierName}: ${x.effects.join(' · ')}`,tier:x.tier,score:x.score}))}
function activeTraditions(){const rows=Object.entries(TRADITION_DEFS).map(([key,d])=>{const p=state.traditionProgressV190?.[key]||{score:0,tier:0};return{key,...d,score:Number(p.score||0),tier:Number(p.tier||0),tierName:tierName(Number(p.tier||0))}}).filter(x=>x.tier>0).sort((a,b)=>b.tier-a.tier||b.score-a.score);return rows.slice(0,3)}
function allTraditions(){ensure();return Object.entries(TRADITION_DEFS).map(([key,d])=>{const p=state.traditionProgressV190[key];return{key,...d,score:p.score,tier:p.tier,tierName:tierName(p.tier)}}).sort((a,b)=>b.tier-a.tier||b.score-a.score)}
