function recruitingBreakdown(r){ensure();if(!r)return{mult:1,pct:0,reasons:[]};let pct=0;const reasons=[],add=(label,value)=>{value=Number(value)||0;if(value>.0001){pct+=value;reasons.push(`${label} +${Math.round(value*100)}%`)}};add('National Brand',effectScale('NATIONAL_BRAND',.01,.015));if(recruitPriority(r,'Pro development')||recruitPriority(r,'PRO'))add('Pro Factory',effectScale('PRO_FACTORY',.02,.02));if(recruitPriority(r,'Academics')||recruitPriority(r,'ACADEMICS'))add('Academic Power',effectScale('ACADEMIC_POWER',.02,.02));if(recruitPriority(r,'Winning')||recruitPriority(r,'WINNING'))add('Championship Standard',effectScale('CHAMPIONSHIP_STANDARD',.02,.02));if((state.school?.pipelines||[]).includes(r.home))add('National Recruiting Reach',effectScale('NATIONAL_REACH',.02,.025));const dist=typeof distance==='function'?Number(distance(state.school,r)||0):0;if(dist>900)add('Long-distance brand reach',effectScale('NATIONAL_BRAND',.006,.012));const mult=clip(1+pct,1,1.18);return{mult,pct:mult-1,reasons}}
