function afterFinishSeason(out){ensure();const wins=Number(state.record?.w||0),extra=wins>=12?5:wins>=10?3:wins>=8?2:1;addFocusedGrowth(`Year ${state.year} season`,extra);for(const key of Object.keys(TRADITION_DEFS)){const p=state.traditionProgressV190[key],before=p.tier;p.score=clip(Math.max(p.score,Math.round(targetScore(key))),0,100);p.tier=tierFor(p.score);if(p.tier>before)state.news?.push(`${TRADITION_DEFS[key].name} became a ${tierName(p.tier)} program tradition.`)}syncLegacyTraditions();return out}
