function scheduleLabel(g){const row=rivalryForGame(g);return row?` · ${row.type==='PRIMARY'?'PRIMARY ':''}RIVALRY · ${tier(row.intensity).toUpperCase()} ${row.intensity}`:''}
function candidateScore(c){return n(c.meetings)*8+n(c.closeGames)*12+n(c.rankedMeetings)*7+n(c.upsetWins)*10+n(c.stakesPoints)*5}
function stakesFor(g){let points=0;if(g.conference)points+=1;if(n(g.oppPower)>=82)points+=1;if(n(g.oppPower)>=90)points+=1;if(state.liveGameContext?.type&&state.liveGameContext.type!=='REGULAR')points+=2;return points}
function trackCandidate(g,win,margin){const r=root(),id=Number(g.oppId);if(!id||id===Number(state.rivalId)||r.rivalries[id])return null;const c=r.candidates[id]??={id,name:g.opponent,meetings:0,wins:0,losses:0,streak:0,bestMargin:0,closeGames:0,rankedMeetings:0,upsetWins:0,stakesPoints:0,lastYear:null,history:[]};c.meetings++;c.wins+=win?1:0;c.losses+=win?0:1;c.streak=win?Math.max(1,n(c.streak)+1):Math.min(-1,n(c.streak)-1);c.bestMargin=Math.max(n(c.bestMargin),win?Math.max(0,n(margin)):0);if(Math.abs(margin)<=7)c.closeGames++;if(n(g.oppPower)>=82)c.rankedMeetings++;const ours=Number(window.teamRatings?.()?.overall||state.school?.prestige||70);if(win&&n(g.oppPower)>=ours+5)c.upsetWins++;c.stakesPoints+=stakesFor(g);c.lastYear=n(state.year);c.history.unshift(meetingRow(g,win,margin));c.history=c.history.slice(0,12);const score=candidateScore(c);if((c.meetings>=3&&score>=28)||(c.meetings>=2&&score>=34)){const row=normalize({id,name:g.opponent,type:'DYNAMIC',formedYear:n(state.year),reason:c.closeGames>=2?'A series of close games turned personal':c.upsetWins?'An upset changed the relationship':'Repeated high-stakes meetings',wins:c.wins,losses:c.losses,streak:c.streak,bestMargin:c.bestMargin,closeGames:c.closeGames,rankedMeetings:c.rankedMeetings,upsetWins:c.upsetWins,stakesPoints:c.stakesPoints,momentum:win?2:-2,lastPlayedYear:n(state.year),last:{year:state.year,win,score:g.score},meetings:c.history.slice()},id,'DYNAMIC');r.rivalries[id]=row;delete r.candidates[id];state.news??=[];state.news.push(`A new ${tier(row.intensity).toLowerCase()} rivalry has formed with ${row.name}: ${row.reason}.`);syncCompat();return row}return null}
function meetingRow(g,win,margin){return{year:n(state.year),week:n(g.week),home:!!g.home,win:!!win,score:String(g.score||''),margin:n(margin),oppPower:n(g.oppPower),conference:!!g.conference,ranked:n(g.oppPower)>=82,stakes:stakesFor(g)}}
function recordGameOutcome(g,win,margin){ensure();if(!g||g._v191RivalryRecorded)return null;g._v191RivalryRecorded=true;let row=rivalryForGame(g);if(!row)return trackCandidate(g,win,margin);const stakesIntensity=n(row.intensity);const ours=Number(window.teamRatings?.()?.overall||state.school?.prestige||70),close=Math.abs(n(margin))<=7,ranked=n(g.oppPower)>=82,upset=!!win&&n(g.oppPower)>=ours+5;row.wins+=win?1:0;row.losses+=win?0:1;row.streak=win?Math.max(1,n(row.streak)+1):Math.min(-1,n(row.streak)-1);row.bestMargin=Math.max(n(row.bestMargin),win?Math.max(0,n(margin)):0);row.closeGames+=close?1:0;row.rankedMeetings+=ranked?1:0;row.upsetWins+=upset?1:0;row.stakesPoints+=stakesFor(g);row.lastPlayedYear=n(state.year);row.last={year:state.year,win:!!win,score:g.score};row.meetings.unshift(meetingRow(g,win,margin));row.meetings=row.meetings.slice(0,24);row.momentum=clip(n(row.momentum)+(win?2:-2),-8,8);row.ownerId=win?userId():Number(g.oppId);row.intensity=calcIntensity(row);
 // Build 302: the swing is set by the intensity going into the game, the same number the Game Day preview shows.
 const sw=outcomeSwing(stakesIntensity,win),fan=Math.abs(sw.fan),boost=Math.abs(sw.booster),job=sw.job,pre={fan:n(state.fanApproval),booster:n(state.boosterSupport),job:n(state.jobSecurity)};state.fanApproval=clip(n(state.fanApproval)+(win?fan:-fan),0,100);state.boosterSupport=clip(n(state.boosterSupport)+(win?boost:-boost),0,100);state.jobSecurity=clip(n(state.jobSecurity)+job,0,100);row.lastSwing={year:n(state.year),week:n(g.week),win:!!win,intensity:stakesIntensity,...sw,applied:{fan:state.fanApproval-pre.fan,booster:state.boosterSupport-pre.booster,job:state.jobSecurity-pre.job}};if(state.coachCareer)state.coachCareer.reputation=clip(n(state.coachCareer.reputation)+(win&&row.intensity>=78?1:!win&&row.intensity>=90?-1:0),20,99);state.achievementStats??={};if(win)state.achievementStats.rivalWins=n(state.achievementStats.rivalWins)+1;state.news??=[];state.news.push(`${win?'Rivalry win':'Rivalry loss'} vs ${row.name}: ${row.trophy} ${win?'comes home':'goes to the rival'} · ${tier(row.intensity)} intensity ${row.intensity} · ${job>=0?'+':''}${job} job security.`);syncCompat();buildWorldPulse();return row}
function recruitingBreakdown(r){ensure();const rivals=Object.values(root().rivalries);if(!rivals.length)return{mult:1,pct:0,reasons:[]};let pct=0;const reasons=[];for(const row of rivals){const o=team(row.id),sharedState=String(r?.home||'')===String(o?.state||''),sharedPipeline=(state.school?.pipelines||[]).includes(r?.home)&&String(r?.home||'')===String(o?.state||'');const base=n(row.momentum)*.0035*(.7+row.intensity/100);if(Math.abs(base)>.001&&(sharedState||sharedPipeline||row.type==='PRIMARY')){const value=base*(sharedState?1.5:1);pct+=value;reasons.push(`${row.name} ${base>=0?'momentum':'setback'} ${value>=0?'+':''}${Math.round(value*100)}%`)}}pct=clip(pct,-.05,.07);return{mult:1+pct,pct,reasons}}
function recruitingMultiplier(r){return recruitingBreakdown(r).mult}
function visitQualityBonus(g){const i=rivalryIntensity(g);return i?Math.round(10+i*.12):0}
function visitBonus(g){const i=rivalryIntensity(g);return i?clip(1+Math.round((i-45)/18),1,5):0}
function attendanceDemandBonus(g){const row=rivalryForGame(g);return row?clip(6+row.intensity*.14,8,20):0}
function revenueMultiplier(g){const row=rivalryForGame(g);return row?clip(1+row.intensity*.0015,1.06,1.15):1}
function gameEdge(g){const row=rivalryForGame(g);if(!row)return 0;const trophy=row.ownerId===userId()?.35:row.ownerId==null?0:-.15;return clip(n(row.momentum)*.11+trophy+(row.intensity>=85?.2:0),-1.1,1.5)}
function coachGoalGame(){ensure();const games=(state.schedule||[]).filter(g=>isRivalGame(g));if(!games.length)return null;return games.slice().sort((a,b)=>rivalryIntensity(b)-rivalryIntensity(a))[0]}
function rebuildGame(g,opp,row){const w=state.world?.find(t=>Number(t.id)===Number(opp.id)),persistent=window.SDF_AI_ROSTERS?.get?.(opp.id),ratings=persistent?.length?window.SDF_AI_ROSTERS?.teamRatings?.(persistent):null;g.opponent=opp.name;g.oppId=opp.id;g.oppPower=Number(ratings?.overall||w?.rosterPower||Math.round((n(opp.prestige,60)+n(opp.recent,60))/2));g.conference=(w?.conference||opp.conference)===state.school.conference;g.rivalry=true;g.rivalryTypeV191=row.type;g.rivalIdV191=row.id;g.weather=typeof weatherForGame==='function'?weatherForGame(g):g.weather;return g}
function markSchedule(){if(!state.schedule?.length)return;const r=root();for(const g of state.schedule){const row=r.rivalries[Number(g.oppId)];if(row){g.rivalry=true;g.rivalryTypeV191=row.type;g.rivalIdV191=row.id}else if(Number(g.oppId)!==Number(state.rivalId)){g.rivalry=false;delete g.rivalryTypeV191;delete g.rivalIdV191}}
 if(r.scheduledYear===n(state.year)||state.schedule.some(g=>g.result)||n(state.week)>1){r.scheduledYear=n(state.year);return}const dynamics=Object.values(r.rivalries).filter(x=>x.type==='DYNAMIC').sort((a,b)=>b.intensity-a.intensity).slice(0,2);const targetWeeks=[10,9];dynamics.forEach((row,index)=>{let existing=state.schedule.find(g=>Number(g.oppId)===row.id);if(existing){rebuildGame(existing,team(row.id),row);return}if(index===1&&row.intensity<80)return;const target=state.schedule.find(g=>g.week===targetWeeks[index]&&!g.result&&Number(g.oppId)!==Number(state.rivalId));if(target){const opp=team(row.id);if(opp)rebuildGame(target,opp,row)}});r.scheduledYear=n(state.year)}
function buildWorldPulse(){if(!state?.school)return[];const r=root(),rows=(state.world||[]).map(t=>{const rec=t.record||{w:0,l:0},games=n(rec.w)+n(rec.l),pct=games?n(rec.w)/games:.5,power=n(t.rosterPower,65)*.42+n(t.prestige,50)*.25+n(t.recent,50)*.23+pct*10;return{id:Number(t.id),name:t.name,power:Math.round(power),prestige:n(t.prestige),recent:n(t.recent),record:`${n(rec.w)}-${n(rec.l)}`,delta:n(t.recent)-n(t.prestige)}}).sort((a,b)=>b.power-a.power);const riser=rows.slice().sort((a,b)=>b.delta-a.delta)[0],faller=rows.slice().sort((a,b)=>a.delta-b.delta)[0],userRank=Math.max(1,rows.findIndex(x=>x.id===userId())+1);r.worldPulse={year:n(state.year),week:n(state.week),powerPrograms:rows.slice(0,6),riser,faller,userPowerRank:userRank};return rows}
function rivalryCards(){return Object.values(root().rivalries).sort((a,b)=>(a.type==='PRIMARY'?-1:0)-(b.type==='PRIMARY'?-1:0)||b.intensity-a.intensity)}
function renderRivalries(){ensure();const rows=rivalryCards(),host=document.getElementById('rivalryV170'),legacy=document.getElementById('rivalryHistory');const html=`<div class="section-head"><div><span class="eyebrow">RIVALRY WORLD · BUILD 191</span><h2>Rivalry Network</h2><p class="muted">Series history now changes intensity, trophies, recruiting momentum, attendance, game edge and coaching pressure. Dynamic rivalries can form and return to future schedules.</p></div><span class="viz-badge">${rows.length} active</span></div><div class="rivalry-network-v191">${rows.map(row=>`<article class="rivalry-card-v191 ${row.type.toLowerCase()}"><div class="rivalry-card-head-v191"><div><span class="eyebrow">${row.type==='PRIMARY'?'PRIMARY RIVAL':'DYNAMIC RIVAL'}</span><h3>${esc(row.name)}</h3></div><strong>${row.intensity}</strong></div><div class="rivalry-tier-v191">${tier(row.intensity)} · ${esc(row.trophy)}</div><div class="metric-grid">${metricV191('Series',`${row.wins}-${row.losses}`)}${metricV191('Streak',row.streak===0?'Even':`${Math.abs(row.streak)} ${row.streak>0?'W':'L'}`)}${metricV191('Trophy',row.ownerId===userId()?'OURS':row.ownerId==null?'Unclaimed':'THEIRS')}${metricV191('Momentum',`${row.momentum>=0?'+':''}${row.momentum}`)}</div><p>${esc(row.reason)}</p>${row.meetings?.length?`<details><summary>Recent meetings</summary><div class="rivalry-meetings-v191">${row.meetings.slice(0,6).map(m=>`<span><b>Year ${m.year}</b> ${m.win?'W':'L'} ${esc(m.score)} · ${m.home?'Home':'Away'}${m.ranked?' · Ranked-quality':''}${Math.abs(m.margin)<=7?' · One-score':''}</span>`).join('')}</div></details>`:''}</article>`).join('')||'<p class="muted">Rivalries will appear once a dynasty begins.</p>'}</div>`;if(host)host.innerHTML=html;if(legacy)legacy.innerHTML=rows.map(row=>`<div class="rivalry-card"><h4>${esc(row.trophy)}</h4><b>${esc(state.school.name)} vs ${esc(row.name)}</b><span class="sub">${tier(row.intensity)} ${row.intensity} · Record ${row.wins}-${row.losses} · ${row.ownerId===userId()?'Trophy held':'Trophy not held'}</span></div>`).join('')}
function metricV191(label,value){return`<div class="metric"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`}
function ensureWorldPanel(){const tab=document.getElementById('dynastyTab');if(!tab||document.getElementById('worldPulseV191'))return;const s=document.createElement('section');s.id='worldPulseV191';s.className='surface world-pulse-v191';const settings=document.getElementById('realismSettingsV170');if(settings)settings.before(s);else tab.appendChild(s)}
function renderWorld(){ensureWorldPanel();const host=document.getElementById('worldPulseV191');if(!host)return;const p=root().worldPulse||{},powers=p.powerPrograms||[];host.innerHTML=`<div class="section-head"><div><span class="eyebrow">NATIONAL WORLD · BUILD 191</span><h2>World Pulse</h2><p class="muted">This is derived from the persistent AI world: roster power, prestige, recent success and current records. These are the same program values used by scheduling, rankings and offseason world progression.</p></div><span class="viz-badge">Your power rank #${p.userPowerRank||'—'}</span></div><div class="world-power-grid-v191">${powers.map((x,i)=>`<article><b>#${i+1} ${esc(x.name)}</b><span>Power ${x.power} · ${x.record}</span></article>`).join('')}</div><div class="two-col"><div class="world-story-v191"><span class="eyebrow">RISING PROGRAM</span><b>${esc(p.riser?.name||'—')}</b><small>Recent success ${p.riser?.recent??'—'} vs prestige ${p.riser?.prestige??'—'}</small></div><div class="world-story-v191"><span class="eyebrow">UNDER PRESSURE</span><b>${esc(p.faller?.name||'—')}</b><small>Recent success ${p.faller?.recent??'—'} vs prestige ${p.faller?.prestige??'—'}</small></div></div>`}
function enhanceRecruitModal(id){const r=(state.recruits||[]).find(x=>String(x.id)===String(id)),body=document.getElementById('modalBody');if(!r||!body||body.querySelector('.recruit-rivalry-v191'))return;const b=recruitingBreakdown(r);if(Math.abs(b.pct)<.001&&!b.reasons.length)return;const html=`<section class="recruit-profile-section recruit-rivalry-v191"><h3>Rivalry Momentum</h3><p class="muted">Recent rivalry results can help or hurt recruiting, especially in a rival's home territory.</p><div class="identity-recruit-line-v190"><div><span class="eyebrow">⚔ Rivalry Network</span><b>${b.pct>=0?'+':''}${Math.round(b.pct*100)}% recruiting influence</b></div><span>${esc(b.reasons.join(' · '))}</span></div></section>`;const identity=body.querySelector('.recruit-identity-v190');if(identity)identity.insertAdjacentHTML('afterend',html);else body.insertAdjacentHTML('beforeend',html)}
