function nextGoal(p,f){if(f.goal==='STARTER')return f.ambition>=75?'STAR':f.leadership>=76?'LEADER':'CHAMPIONSHIP';if(f.goal==='STAR')return n(p.year)>=3&&f.ambition>=72?'NFL':'CHAMPIONSHIP';if(f.goal==='LEADER')return f.ambition>=78&&n(p.year)>=3?'NFL':'CHAMPIONSHIP';if(f.goal==='CHAMPIONSHIP')return n(p.year)>=3&&f.ambition>=72?'NFL':f.leadership>=78?'LEADER':'CHAMPIONSHIP';if(f.goal==='DEGREE')return n(p.year)>=3?'DEGREE':p.starter?'CHAMPIONSHIP':'STARTER';return f.goal}
function seasonReview(){ensure();for(const p of state.roster||[]){const f=ensurePlayer(p),goal=goalStatus(p);if(goal.met&&!f.goalMetYears?.includes?.(state.year)){f.goalMetYears=Array.isArray(f.goalMetYears)?f.goalMetYears:[];f.goalMetYears.push(state.year);f.pendingNextGoal=nextGoal(p,f);f.coachBond=clip(f.coachBond+3);f.loyalty=clip(f.loyalty+2);addStory(p,'GOAL',`${p.name} achieved his goal: ${goal.label}.`)}if(p.starter&&seasonProduction(p)>=6)addStory(p,'BREAKOUT',`${p.name} produced a breakout season as a ${p.pos}.`)}}
function advanceGoals(){for(const p of state.roster||[]){const f=ensurePlayer(p);if(f.pendingNextGoal&&GOALS[f.pendingNextGoal]){const old=GOALS[f.goal]?.label;f.goal=f.pendingNextGoal;delete f.pendingNextGoal;if(GOALS[f.goal]?.label!==old)addStory(p,'GOAL',`${p.name}'s next goal is to ${GOALS[f.goal].label.toLowerCase()}.`)}}}
function afterPromiseResolution(promise,kept){const p=(state.roster||[]).find(x=>x.id===promise?.targetId);if(!p)return;const f=ensurePlayer(p);if(kept){f.coachBond=clip(f.coachBond+6);f.loyalty=clip(f.loyalty+3);addStory(p,'PROMISE',`Coach kept the ${promise.type} promise to ${p.name}.`)}else{const shock=p.personality==='Volatile'?10:p.personality==='Loyal'?7:8;f.coachBond=clip(f.coachBond-shock);f.loyalty=clip(f.loyalty-Math.round(shock*.55));addStory(p,'PROMISE',`The ${promise.type} promise to ${p.name} was broken.`)}}
function earlyEntryChanceMultiplier(p){const f=ensurePlayer(p);let m=1+(f.ambition-65)*.012-(f.loyalty-65)*.004;if(f.goal==='NFL')m+=.22;if(f.goal==='DEGREE')m-=.35;if(f.coachBond>=82)m-=.08;return clip(m,.45,1.45)}
function portalReason(p){const f=ensurePlayer(p),goal=goalStatus(p);if(f.coachBond<45)return'Lost confidence in the coaching relationship';if(f.loyalty<45)return'Seeking a fresh start';if(goal.key==='STARTER'&&!p.starter)return'Wants a starting opportunity';if(goal.key==='STAR'&&usage(p).avgSnap<30)return'Wants a featured role';if(p.personality==='Homesick')return'Wants to be closer to home';if(p.personality==='Money-driven')return'Seeking a bigger NIL / pro opportunity';return'Role and program fit concerns'}
