function beforeRender(){ensure();scanGames();syncCaptains()}
function afterRender(out){enhanceRoster();enhanceLeadership();return out}
const base={openPlayerProfile:window.openPlayerProfile,offseason:window.offseason,finishSeason:window.finishSeason,runDraft:window.runDraft,takePortal:window.takePortal,setCaptain:window.setCaptain};
window.openPlayerProfile=function(id,...args){const out=base.openPlayerProfile?.apply(this,[id,...args]);enhancePlayerProfile(id);return out};
window.setCaptain=function(id,...args){const before=(state.captains||[]).includes(id),out=base.setCaptain?.apply(this,[id,...args]);const p=(state.roster||[]).find(x=>x.id===id);if(p){const f=ensurePlayer(p),after=(state.captains||[]).includes(id);if(after&&!before){f.leadership=clip(f.leadership+1);f.coachBond=clip(f.coachBond+3);addStory(p,'CAPTAIN',`${p.name} was named a team captain.`)}}enhanceLeadership();return out};
window.takePortal=function(id,...args){const portal=(state.portal||[]).find(x=>x.id===id);if(portal)ensurePlayer(portal,{origin:'Transfer portal'});const out=base.takePortal?.apply(this,[id,...args]);const signed=(state.roster||[]).find(x=>x.id===id||x.name===portal?.name);if(signed){const f=ensurePlayer(signed,{origin:'Transfer portal'});f.coachBond=clip(f.coachBond+4);addStory(signed,'ARRIVAL',`${signed.name} transferred in seeking ${portal?.reason?.toLowerCase()||'a new opportunity'}.`)}return out};
window.finishSeason=function(...args){seasonReview();return base.finishSeason?.apply(this,args)};
window.offseason=function(...args){ensure();const before=(state.roster||[]).map(p=>JSON.parse(JSON.stringify(p))),out=base.offseason?.apply(this,args);ensure();archiveDepartures(before);advanceGoals();for(const p of state.roster||[]){const f=ensurePlayer(p);if(f.lastYear!==n(state.year)){f.lastYear=n(state.year);f.lastOvr=n(p.ovr)}}return out};
window.runDraft=function(...args){const before=(state.draftEligibleClass||[]).map(p=>JSON.parse(JSON.stringify(p))),out=base.runDraft?.apply(this,args);for(const p of before){const d=(state.draftHistory||[]).find(x=>String(x.playerId||'')===String(p.id)&&Number(x.year)===Number(state.year));if(d){ensurePlayer(p);addStory(p,'DRAFTED',`${p.name} was drafted in Round ${d.round}, Pick ${d.pick}.`)}}archiveDepartures(before);return out};
if(window.SDF_AI_ROSTERS?.juniorDeclares){const prior=window.SDF_AI_ROSTERS.juniorDeclares;window.SDF_AI_ROSTERS.juniorDeclares=function(p,evaluation,context={}){const userCandidate=(state.draftEligibleClass||[]).some(x=>String(x.id)===String(p.id))||(state.roster||[]).some(x=>String(x.id)===String(p.id));if(!userCandidate)return prior(p,evaluation,context);ensurePlayer(p);const baseChance=evaluation?.score>=104?.985:evaluation?.score>=100?.94:evaluation?.score>=96?.80:evaluation?.score>=92?.58:evaluation?.score>=88?.30:evaluation?.score>=84?.12:.03,mult=earlyEntryChanceMultiplier(p),seed=(hash(`v192-declare-${context.year||state.year}-${p.id}`)%100000)/100000;return seed<clip(baseChance*mult,0,.995)}}
window.SDF_V192={version:VERSION,build:BUILD,PERSONALITIES,GOALS,ensure,ensurePlayer,goalStatus,transferRiskMultiplier,developmentChanceBonus,academicRiskMultiplier,captainScore,captainTeamBonus,cultureLeadershipScore,personalityMoraleScale,earlyEntryChanceMultiplier,portalReason,addStory,afterPromiseResolution,enhancePlayerProfile,lifecycle:{beforeRender,afterRender}};
