const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'$'+(Math.round(n(v)/1000)).toLocaleString()+'k';
function programId(){return Number(state.school?.id||0)}
function initialAdmin(){return Math.round(clip(n(state.jobSecurity,70)*.55+n(state.school?.recent,55)*.25+n(state.coachCareer?.reputation,50)*.20,35,90))}
function ensure(){
 if(!state?.school)return null;
 state.fanApproval=clip(state.fanApproval??65);state.boosterSupport=clip(state.boosterSupport??65);
 let s=state.stakeholdersV193;
 if(!s||typeof s!=='object')s=state.stakeholdersV193={};
 if(Number(s.programId)!==programId()){
  s.programId=programId();s.adminConfidence=initialAdmin();s.actionsYear=Number(state.year||1);s.actions={};s.annualReview=null;s.dismissedYear=null;s.ultimatumYear=null;s.history=[];
 }
 s.version=BUILD;s.adminConfidence=clip(s.adminConfidence??initialAdmin());s.actions=s.actions&&typeof s.actions==='object'?s.actions:{};s.history=Array.isArray(s.history)?s.history:[];
 if(Number(s.actionsYear)!==Number(state.year)){s.actionsYear=Number(state.year);s.actions={}}
 return s
}
function coachTenure(){return Math.max(1,Number(state.year||1)-Number(state.coachCareer?.currentJobStartYear||1)+1)}
function adminPatience(){const prestige=n(state.school?.prestige,60),tenure=coachTenure(),rebuild=prestige<62?10:0;return Math.round(clip(78-prestige*.42+Math.min(12,tenure*2)+rebuild,28,78))}
function adminStatus(){const s=ensure(),c=s.adminConfidence,j=n(state.jobSecurity,70);if(s.dismissedYear===state.year)return'DISMISSED';if(j<25||c<30)return'HOT SEAT';if(j<45||c<48)return'UNDER REVIEW';if(j>=80&&c>=75)return'FULL SUPPORT';return'STABLE'}
function firingThreshold(){return Math.round(clip(10+(55-adminPatience())*.18,8,18))}
function allocationMultiplier(){const s=ensure();return clip(1+(n(state.boosterSupport,60)-60)*.002+(n(s.adminConfidence,60)-60)*.0015,.88,1.16)}
function facilityCostMultiplier(){const s=ensure();return clip(1-(Math.max(0,n(state.boosterSupport)-70)*.0015+Math.max(0,n(s.adminConfidence)-72)*.0012),.90,1)}
function recruitingMultiplier(r){ensure();let pct=0,priority=String(r?.priority||'').toLowerCase();if(priority.includes('nil'))pct+=(n(state.boosterSupport)-60)*.0011;if(priority.includes('winning'))pct+=Math.max(0,n(state.fanApproval)-65)*.00055;return clip(1+pct,.96,1.07)}
function visitMultiplier(){ensure();return clip(1+(n(state.fanApproval)-55)*.0008+(n(state.boosterSupport)-60)*.00025,.97,1.06)}
function homeFieldEdge(){ensure();return clip((n(state.fanApproval)-55)*.018,-.45,.85)}
function attendanceDemandBonus(){ensure();return clip((n(state.fanApproval)-60)*.16,-5,7)}
function revenueMultiplier(){ensure();return clip(1+(n(state.fanApproval)-60)*.0012+(n(state.boosterSupport)-60)*.0008,.94,1.09)}
function staffDepartureMultiplier(){const s=ensure();return clip(1-(n(s.adminConfidence)-60)*.0025-(n(state.boosterSupport)-60)*.0018,.76,1.24)}
function collectiveContribution(){return Math.round((35000+n(state.boosterSupport)*850+n(state.school?.prestige)*350)/5000)*5000}
function currentGoalRate(){const e=state.seasonExpectations?.evaluation;if(e&&Number.isFinite(Number(e.rate)))return Number(e.rate);const rows=window.SDF_V170?.makeExpectations?null:null;const wins=n(state.record?.w),target=n(state.seasonExpectations?.expectedWins||state.school?.expectation,6);return clip(.5+(wins-target)*.07,0,1)}
function reviewSeason(out){
 const s=ensure();if(!s||Number(s.lastReviewYear)===Number(state.year))return out;
 const e=state.seasonExpectations?.evaluation,rate=Number.isFinite(Number(e?.rate))?Number(e.rate):currentGoalRate(),wins=n(state.record?.w),expected=n(state.seasonExpectations?.expectedWins||state.school?.expectation,6),over=wins-expected;
 let fan=rate>=.9?6:rate>=.72?3:rate>=.5?0:rate>=.32?-4:-7;
 let boosters=rate>=.9?5:rate>=.72?3:rate>=.5?0:rate>=.32?-4:-7;
 let admin=rate>=.9?7:rate>=.72?4:rate>=.5?0:rate>=.32?-6:-10;
 if(over>=3){fan+=2;boosters+=2;admin+=2}if(over<=-3){fan-=2;boosters-=2;admin-=2}
 const playoff=!!state.postseasonData?.playoffField?.some?.(t=>Number(t.id)===programId());if(playoff){fan+=2;boosters+=2;admin+=2}
 state.fanApproval=clip(n(state.fanApproval)+fan);state.boosterSupport=clip(n(state.boosterSupport)+boosters);s.adminConfidence=clip(n(s.adminConfidence)+admin);
 if(s.adminConfidence>=80&&rate>=.72)state.jobSecurity=clip(n(state.jobSecurity)+2);if(s.adminConfidence<30&&rate<.5)state.jobSecurity=clip(n(state.jobSecurity)-3);
 const threshold=firingThreshold();let verdict='RETAINED';if(state.challengeV237?.status==='active'){s.dismissedYear=null;verdict='SCENARIO TENURE'}else if(n(state.jobSecurity)<=threshold&&s.adminConfidence<30&&rate<.5){s.dismissedYear=Number(state.year);verdict='DISMISSED'}else if(n(state.jobSecurity)<35||s.adminConfidence<38){s.ultimatumYear=Number(state.year)+1;verdict='ULTIMATUM'}
 s.lastReviewYear=Number(state.year);s.annualReview={year:state.year,rate,fanDelta:fan,boosterDelta:boosters,adminDelta:admin,jobSecurity:n(state.jobSecurity),threshold,verdict};s.history.push({...s.annualReview});s.history=s.history.slice(-12);
 state.news??=[];state.news.push(`Administration review: ${Math.round(rate*100)}% of weighted goals met · ${verdict.toLowerCase()} · Fan ${fan>=0?'+':''}${fan}, boosters ${boosters>=0?'+':''}${boosters}, administration ${admin>=0?'+':''}${admin}.`);
 if(verdict==='DISMISSED')state.news.push(`${state.school.name} dismissed ${state.coachCareer?.name||'the head coach'} after the Year ${state.year} review. The coaching carousel will require a new job.`);
 return out
}
function afterFinishOffseason(oldYear,out){if(Number(state.year)!==Number(oldYear)){const s=ensure();s.actionsYear=Number(state.year);s.actions={};const grant=collectiveContribution();state.nilBudget=n(state.nilBudget)+grant;state.news??=[];state.news.push(`Boosters opened Year ${state.year} with a ${money(grant)} NIL collective contribution.`);if(s.ultimatumYear&&Number(s.ultimatumYear)===Number(state.year))state.news.push('Administration ultimatum active: this season must restore job security and administrative confidence.')}return out}
function mustLeaveCurrentJob(){const s=ensure();if(state.challengeV237?.status==='active'){if(s)s.dismissedYear=null;return false}return !!s&&Number(s.dismissedYear)===Number(state.year)}
function onAcceptJob(){const s=ensure();if(!s)return;s.programId=programId();s.adminConfidence=initialAdmin();s.dismissedYear=null;s.ultimatumYear=null;s.actionsYear=Number(state.year);s.actions={};s.annualReview=null}
function initiative(type){
 const s=ensure();if(!s||s.actions[type])return false;let cost=0,msg='';
 if(type==='BOOSTERS'){cost=35000;if(n(state.budget)<cost)return false;state.budget-=cost;state.boosterSupport=clip(n(state.boosterSupport)+6);const nil=Math.round((40000+n(state.boosterSupport)*600)/5000)*5000;state.nilBudget=n(state.nilBudget)+nil;s.adminConfidence=clip(s.adminConfidence+1);msg=`Booster summit raised support and added ${money(nil)} to the NIL collective.`}
 if(type==='FANS'){cost=25000;if(n(state.budget)<cost)return false;state.budget-=cost;state.fanApproval=clip(n(state.fanApproval)+6);if(state.stadium)state.stadium.atmosphere=clip(n(state.stadium.atmosphere)+2);msg='Fan engagement campaign raised approval and stadium atmosphere.'}
 if(type==='ADMIN'){const gain=n(state.jobSecurity)>=65?5:n(state.jobSecurity)>=45?3:1;s.adminConfidence=clip(s.adminConfidence+gain);msg=`Program review meeting improved Administration Confidence by ${gain}.`}
 if(type==='BUDGET'){if(s.adminConfidence<52)return false;const grant=Math.round((50000+s.adminConfidence*1400+n(state.boosterSupport)*900)/10000)*10000;state.budget=n(state.budget)+grant;s.adminConfidence=clip(s.adminConfidence-3);msg=`Administration approved ${money(grant)} in supplemental program funds; political capital fell slightly.`}
 if(!msg)return false;s.actions[type]=true;state.news??=[];state.news.push(msg);window.renderAll?.();window.SDF_RELEASE_TEST?.saveNow?.(`Stakeholder action: ${type}`,false,false);return true
}
