 const builder=clip(44+Math.min(13,yrs*1.15)+Math.max(0,traj)*1.25+n(a.rebuildPlayoffs)*4+Math.max(0,n(state.school?.prestige,50)-50)*.12+Math.max(0,n(state.teamCultureV188,55)-55)*.08+Math.max(0,n(window.SDF_V193?.ensure?.()?.adminConfidence,55)-55)*.07);
