function refreshMilestones(x=identity()){const a=state.achievementStats||{},cw=n(state.coachCareer?.careerWins);if(!x.story.length)addStory('career-start',`${state.coachCareer?.name||'Coach'} began building a head-coaching résumé.`);for(const mark of [25,50,100,150,200])if(cw>=mark)addStory(`wins-${mark}`,`Reached ${mark} career victories.`);for(const mark of [1,5,10,20])if(n(a.totalDrafted)>=mark)addStory(`drafted-${mark}`,`Developed ${mark} players who were selected in the pro draft.`);if(n(a.nationalTitles)>=1)addStory('first-title','Won a national championship.');if(n(a.nationalTitles)>=3)addStory('titles-3','Built a three-time national championship résumé.');if(n(a.conferenceTitles)>=1)addStory('first-conf-title','Won a conference championship.');const t=tier(x.reputations?.national);if(t!==x.lastTier){if(x.lastTier)addStory(`tier-${t}`,`Coaching reputation reached ${t.toLowerCase()} status.`);x.lastTier=t}}
