function jobProfile(s,ctx={}){const r=calculate().reputations,jobType=ctx.jobType||'LATERAL',prestige=n(s?.prestige,55),recent=n(s?.recent,55),need=Math.max(0,prestige-recent);let weights,priority;if(jobType==='REBUILD'){weights={builder:.40,developer:.25,recruiting:.20,gameDay:.05,national:.10};priority='Program building + player development'}else if(jobType==='PROMOTION'){weights={gameDay:.42,recruiting:.20,developer:.10,builder:.08,national:.20};priority='Winning + national credibility'}else if(need>=10){weights={builder:.33,developer:.24,recruiting:.23,gameDay:.08,national:.12};priority='Roster repair + long-term build'}else{weights={gameDay:.27,recruiting:.23,developer:.20,builder:.17,national:.13};priority='Balanced head-coach profile'}let score=0;for(const [k,w] of Object.entries(weights))score+=r[k]*w;const required=44+prestige*.43;let loyaltyAdj=0;if(prestige>=78)loyaltyAdj=(r.loyalty-65)*.09;else if(jobType==='REBUILD')loyaltyAdj=(r.loyalty-55)*.035;const delta=clip((score-required)*.48+loyaltyAdj,-18,18);const final=clip(score+loyaltyAdj,20,99),label=final>=86?'ELITE FIT':final>=76?'STRONG FIT':final>=66?'SOLID FIT':final>=56?'MIXED FIT':'LONG SHOT';return{score:Math.round(final),delta:Number(delta.toFixed(2)),label,priority,required:Math.round(required),identity:identity().identityLabel,loyalty:r.loyalty}}
