 const program=currentProgram(school.id)||school,old=n(x.ovr,60),gain=n(window.SDF_V111_TEST?.aiProgressGain111?.(x,program),1),ceiling=Math.max(old,n(x.pot,old));x.ovr=clip(Math.min(ceiling,old+gain),45,99);x.year=clip(n(x.year,1)+1,1,4);x.morale=clip(n(x.morale,72)+2,50,99);x.starter=false;x.depthIndex=99;x.redshirt=false;x.progressionHistory=Array.isArray(x.progressionHistory)?x.progressionHistory:[];x.progressionHistory.push({dynastyYear:n(state.year),from:old,to:x.ovr,gain:x.ovr-old,classBefore:n(p.year),classAfter:x.year,transfer:true});x.progressionHistory=x.progressionHistory.slice(-8);x.seasonStats={};x.gameLog=[];x.stats={games:0,yards:0,td:0,tackles:0,sacks:0,int:0};x.rosterOrigin='Transfer portal';x.transferOrigin=school.name;return x
