function draftLikely(p,school){if(n(p.year)!==3)return false;try{const program=currentProgram(school.id)||school,wr=(state.world||[]).find(t=>Number(t.id)===Number(school.id)),e=window.SDF_AI_ROSTERS?.evaluateDraftProspect?.(p,{year:state.year,wins:n(wr?.record?.w),losses:n(wr?.record?.l),pro:n(program.pro,50)});return !!e?.round&&n(e.round)<=4}catch{return n(p.ovr)>=89}}
let opportunityCacheYear=null,opportunityCache=new Map();
function resetOpportunityCache(){opportunityCacheYear=Number(state.year);opportunityCache=new Map();programCacheYear=Number(state.year);programCache=new Map()}
function opportunityRoom(teamId,pos){if(opportunityCacheYear!==Number(state.year))resetOpportunityCache();teamId=Number(teamId);let byPos=opportunityCache.get(teamId);if(!byPos){byPos=new Map();opportunityCache.set(teamId,byPos)}if(byPos.has(pos))return byPos.get(pos);const ovs=aiRoster(teamId).filter(x=>x.pos===pos).map(x=>n(x.ovr)).sort((a,b)=>b-a),starters=Math.max(1,n((typeof STARTERS!=='undefined'&&STARTERS?.[pos])||1,1)),room={best:ovs[0]??null,cut:ovs[starters-1]??null};byPos.set(pos,room);return room}
