function syncRatings(c){const b=c.baseRatings||{};c.recruiting=clip(Math.round(n(b.recruiting,60)+skillEffect(c,'recruitingRating')),40,99);c.development=clip(Math.round(n(b.development,60)+skillEffect(c,'developmentRating')),40,99);c.game=clip(Math.round(n(b.game,60)+skillEffect(c,'gameRating')),40,99);return c}
function branchSequence(c){const primary=BRANCH_SKILLS[c.branch]||BRANCH_SKILLS.Recruiter,secondary=BRANCH_SKILLS[BRANCHES[(BRANCHES.indexOf(c.branch)+1+(hash(c.id)%4))%BRANCHES.length]]||[];return[...primary,...secondary]}
