 let active=sectionState.get(tabId);const visible=sections.filter(s=>!s.classList.contains('hidden'));if(!visible.length)return;if(!visible.some(s=>s.dataset.uiSectionKey===active))active=visible[0].dataset.uiSectionKey;sectionState.set(tabId,active);
 nav.innerHTML=sections.map((s,i)=>`<button type="button" class="ui-section-chip ${s.dataset.uiSectionKey===active?'active':''} ${s.classList.contains('hidden')?'hidden':''}" data-ui-section-key="${s.dataset.uiSectionKey}">${esc(navLabel(s,i))}</button>`).join('');
 nav.querySelectorAll('button:not(.hidden)').forEach(b=>b.addEventListener('click',()=>{sectionState.set(tabId,b.dataset.uiSectionKey);applyNavigator(tabId,true)}));applyNavigator(tabId,false);
