 const tab=$(tabId);if(!tab)return;const active=sectionState.get(tabId),sections=directSections(tab);sections.forEach(s=>{s.classList.remove('subview-hidden');const shouldHide=!s.classList.contains('hidden')&&s.dataset.uiSectionKey!==active;s.classList.toggle('ui219-panel-hidden',shouldHide)});tab.querySelectorAll(':scope > .ui-section-nav-v219 .ui-section-chip').forEach(b=>b.classList.toggle('active',b.dataset.uiSectionKey===active));if(scroll)window.scrollTo({top:0,behavior:'smooth'});
