 let nav=$('recruitingQuickNavV219');if(!nav){nav=document.createElement('nav');nav.id='recruitingQuickNavV219';nav.className='ui-section-nav-v219 ui-recruit-nav-v219';nav.setAttribute('aria-label','Recruiting sections');tab.prepend(nav)}
