function refresh(){
 try{
 decorateScreens();decorateSectionMenus();polishModals();
 if(!stateReady())return;
 exposeHomeControls();polishChecklist();polishRecruiting();polishRoster();polishDepth();polishTables();polishField();
 }finally{
  // These changes are the result of a refresh, not a new source render.
  // Consuming only our synchronous records prevents observer feedback loops.
  uiObservers.forEach(observer=>observer.takeRecords());
 }
}

function wrap(name,afterDelay=20){
 const base=window[name];if(typeof base!=='function'||base.__phoneUiV232)return;
 const wrapped=function(...args){const result=base.apply(this,args);scheduleRefresh(afterDelay);return result};wrapped.__phoneUiV232=true;window[name]=wrapped;
}

