  retry=5000;lastDeliveryError=null;singleEventRetry=false;if(deliveryFailures){const duration_ms=Math.min(300000,Math.max(0,Date.now()-deliveryFailedAt)),delivery_failures=Math.min(10000,deliveryFailures),transport_code=transportCode||'network';deliveryFailures=0;deliveryFailedAt=0;transportCode=null;technical('reporting_recovered','transport',{duration_ms,delivery_failures,transport_code})}if(dropped){dropped=0;safeRecord('reporting_queue_dropped',undefined,undefined,{reason:'queue_limit'})}
