 const d=s.postseasonData||{},id=Number(s.school.id),games=[...(d.conferenceResults||[]),...(d.bowlResults||[]),...(d.playoffRounds||[]).flatMap(r=>r?.games||[])];
 for(const g of games){if(!g?.winner||![g.a?.id,g.b?.id].some(x=>Number(x)===id))continue;keys.push(postseasonKey(g.label,Number(g.a.id)===id?g.b.id:g.a.id))}
