 function restore(point){if(!point||point.page!==document.querySelector('.tab-page:not(.hidden)'))return;for(const s of point.scrollers)if(s.node.isConnected){s.node.scrollTop=s.top;s.node.scrollLeft=s.left}if(point.focus?.isConnected)point.focus.focus?.({preventScroll:true});window.scrollTo({top:point.y,left:point.x,behavior:'instant'})}
