M.registerReward('PREPARATION',{configKey:'rewardedPreparationId',capture:()=>{const c={owner:state,game:state.liveGame,kind:'PREPARATION'};return c.game&&halfValid(c)?c:null},valid:halfValid,grant:c=>{if(!halfValid(c))return false;claimHalf(c);state.news.push('Halftime preparation: +2 offensive and defensive execution rating for quarters 3 and 4 only.');return true},success:'Second-half preparation applied: +2 offensive and defensive execution in Q3–Q4.'});

