 const r=recruit(id),host=document.querySelector('[data-recruit-panel-v226="recruiting"]');if(!r||!host||!native())return;

 const reason=edgeReason(r),winReason=winBackReason(r),el=panel('recruitSponsor283','Optional sponsor meeting','Recruiting Edge: schedule up to +4 relationship influence for the next weekly decision. Once per prospect per week, three prospects per week. Priorities, dealbreakers and decision timing still apply.');

 el.appendChild(button('EDGE',id,'Watch for Recruiting Edge',reason));if(reason){const p=document.createElement('p');p.textContent=reason;el.appendChild(p)}

