 const preparation=document.createElement('p');preparation.textContent=preparationDone?'Second-half preparation applied: +2 offensive and defensive execution in Q3–Q4.':'Preparation: +2 offensive and defensive execution rating in Q3–Q4. No permanent rating change or guaranteed win.';el.appendChild(preparation);
 if(!preparationDone)el.appendChild(button('PREPARATION',null,'Watch Ad for Second-Half Preparation'));

