 if(!native())return;const body=overlay.querySelector('.recruit-recap-body280');if(body){const results=(state.recruits||[]).filter(r=>r.edge283?.key===`${recap.year}-${recap.week}`&&r.edge283.result);if(results.length){const section=document.createElement('section');section.className='sponsor-bonus283';section.innerHTML='<h3>Sponsor recruiting pushes</h3>'+results.map(r=>`<p><b>${esc(r.name)}</b> · ${esc(r.edge283.result)}</p>`).join('');body.appendChild(section)}}const articles=[...overlay.querySelectorAll('.recruit-recap-body280 article')];let index=0;

