 for(const e of recap.events.filter(x=>x.kind==='flipsOut')){const r=recruit(e.id),article=articles.find(a=>a.querySelector('b')?.textContent.startsWith(e.name+' ·'));if(!r||!article)continue;

 const detail=document.createElement('div');detail.className='sponsor-bonus283';const race=R.race(r),portrait=window.SDF_UI_V219?.portraitMarkup?.(r,'recruit')||'';detail.innerHTML=portrait+`<p>${esc(r.city)}, ${esc(r.home)} · Your interest ${Math.round(race.user?.score||0)} · Fit ${esc(race.user?.grade||'—')}</p><p>${r.scouted?`Scouted overall ${esc(r.ovr)} · Projected upside ${esc(window.projectedRecruitUpside?.(r)||'—')}`:'Not scouted — ratings remain hidden.'}</p><p>Return him as a soft commit. One win-back meeting per recruit; he can reconsider before signing.</p>`;

 const why=winBackReason(r);detail.appendChild(button('WINBACK',r.id,'Watch Ad & Bring Back',why));if(why){const p=document.createElement('p');p.textContent=why;detail.appendChild(p)}const alternative=document.createElement('p');alternative.textContent='Or view his profile and try to win him back through normal recruiting.';detail.appendChild(alternative);const view=button('VIEW',r.id,'View Profile');view.onclick=()=>{window.SDF_RECRUITING280.closeRecap();window.openRecruit(r.id)};detail.appendChild(view);article.appendChild(detail);index++}

