const featured=[]; // No league packs are bundled; downloads come from the separate community service.
function loadSession(){if(sharingSignedOut)return null;if(session)return session;try{session=JSON.parse(localStorage.getItem(SESSION)||localStorage.getItem('SDF_SUPABASE_SESSION')||'null')}catch{}return session}
function saveSession(value){sharingSignedOut=!value;session=value;try{if(value)localStorage.setItem(SESSION,JSON.stringify(value));else localStorage.removeItem(SESSION)}catch{}}
async function boundedText(response,max=MAX){if(!response.ok){let message='Library unavailable. Please try again later.';try{message=(await response.json()).error||message}catch{}throw Error(message)}if(Number(response.headers.get('content-length')||0)>max)throw Error('League file is too large.');const reader=response.body?.getReader();if(!reader){const value=await response.text();if(new TextEncoder().encode(value).length>max)throw Error('League file is too large.');return value}let chunks=[],size=0;try{for(;;){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>max){await reader.cancel();throw Error('League file is too large.')}chunks.push(value)}}finally{reader.releaseLock()}const bytes=new Uint8Array(size);let offset=0;for(const part of chunks){bytes.set(part,offset);offset+=part.length}return new TextDecoder().decode(bytes)}
async function refreshSession(){const s=loadSession();if(!s?.refresh_token)return s;if(s.expires_at&&s.expires_at*1000>Date.now()+60000)return s;const r=await fetch(AUTH+'/token?grant_type=refresh_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},credentials:'omit',body:JSON.stringify({refresh_token:s.refresh_token})});if(!r.ok){saveSession(null);return null}saveSession(await r.json());return session}
async function request(path='',options={},authenticated=false){const s=authenticated?await refreshSession():null;if(authenticated&&!s?.access_token)throw Error('Sign in to share a community league.');return fetch(ENDPOINT+path,{...options,credentials:'omit',headers:{apikey:KEY,...(s?.access_token?{Authorization:'Bearer '+s.access_token}:{}),...options.headers}})}
async function list(query='',sort='top'){const r=await request('?q='+encodeURIComponent(query)+'&sort='+encodeURIComponent(sort));const data=JSON.parse(await boundedText(r,128*1024));if(!Array.isArray(data.leagues))throw Error('Invalid community library response.');return data.leagues}
async function readPack(entry){const r=await request('?id='+encodeURIComponent(entry.id));const data=JSON.parse(await boundedText(r));return window.SDF_LEAGUE292.validate(data)}
async function authenticate(email,password,signup=false){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||password.length<8)throw Error('Enter an email and a password of at least 8 characters.');const r=await fetch(AUTH+(signup?'/signup':'/token?grant_type=password'),{method:'POST',credentials:'omit',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});let data;try{data=await r.json()}catch{throw Error('Account service unavailable. Please try again.')}if(!r.ok)throw Error(data.msg||data.error_description||'Could not sign in.');if(!data.access_token)throw Error('Account created. Complete any required email confirmation, then sign in.');saveSession(data);return data}
async function upload(meta,pack){const checked=window.SDF_LEAGUE292.validate(pack),body=JSON.stringify({title:meta.title,author_name:meta.author_name,description:meta.description,league:checked});if(new TextEncoder().encode(body).length>MAX)throw Error('This league exceeds the 8 MB community file limit.');const r=await request('',{method:'POST',headers:{'Content-Type':'application/json'},body},true);return JSON.parse(await boundedText(r,16384))}
