function isOpen(n){return n.matches('dialog')?n.open:!!n.getClientRects().length&&!n.hidden&&!n.classList.contains('hidden')&&(n.id==='mobileMoreMenu'||n.id==='modal'||n.id==='appSettingsModal'||n.id==='tutorialPanel'||n.id==='recruitRecap280'||n.id==='gameSimModal'||n.id==='gameResultModal'||n.classList.contains('open'))}
