 const panel=$('seasonWrap239');let box=panel?.querySelector('.season-awards303');
 if(!panel||state?.phase!=='AWARDS'){box?.remove();return}
 const key=`${state.school?.id}:${state.year}`;if(key!==expandedKey){expandedKey=key;expanded=false}
